/// One staged control with an evidenced behaviour.
const fn routed(code: u32, id: &'static str, action: RoomControlAction) -> RoomControl {
    RoomControl { code, id, action }
}

/// One staged control with no evidenced behaviour yet.
const fn unwired(code: u32, id: &'static str, next_step: &'static str) -> RoomControl {
    routed(code, id, RoomControlAction::Unwired { next_step })
}

/// True while the staged rect of `code` covers native pixel (`x`, `y`).
fn staged_code_hit(placements: &[ScenePlacement], code: u32, x: i32, y: i32) -> bool {
    placements
        .iter()
        .any(|placed| placed.code == code && rect_hit(&placed.rect, x, y))
}

/// Default-title index for a create-room dialog opening now: the exe
/// seeds the C runtime generator from the tick clock and keeps
/// `rand() % 8` (files `0x436a2e`–`0x436a5d`), so every open lands on
/// one of the eight titles. Wall-clock nanoseconds give the same
/// spread without the generator (the exe's seed-to-index mapping is
/// not reproduced, only its uniformity).
fn opening_default_title_index() -> usize {
    let elapsed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |since_epoch| since_epoch.subsec_nanos());
    usize::try_from(elapsed).unwrap_or(0)
}

/// Room chrome already showing its active frame outside the mode tabs:
/// the chat tab (`CHAT_ALL`) paints body frame 1 and never changes on
/// hover (EXE-pinned, `docs/hover.md`). The active mode tab is computed
/// from [`RoomListFilter`] instead. Hover over an active control resolves
/// to nothing, so the painter never repaints frame 1 with frame 0.
const ROOM_ACTIVE_CHROME_CODES: [u32; 1] = [0x1320_100E];

/// Unsent chat draft cap (characters, not bytes: multibyte input
