    pub const fn question1_dialog_art(&self) -> Option<&SceneArt> {
        self.planet_quit_art.as_ref()
    }

    /// Stage the one-OK information sheet (`Dialog_Information.bnd`
    /// placements plus figures) for the relay-down notice. Staging
    /// never opens the modal (#244).
    pub fn load_relay_down_scene(
        &mut self,
        placements: Vec<ScenePlacement>,
        figures: HashMap<String, AvatarFigure>,
    ) -> &mut Self {
        self.relay_down_art = Some(SceneArt {
            placements,
            figures,
        });
        self
    }

    /// Modal click: the quit popup's OK/CANCEL (staged dialog
    /// rects when art is staged, the fallback boxes otherwise) or
    /// the options dialog's staged buttons (EXIT closes without
    /// saving, SAVE commits to `option.ini`, DEFAULT restores the
    /// tab's exe defaults, tab switches flip the sheet, and the
    /// Key/Sound/Game buttons edit the settings — staged rects
    /// only, Escape closes the unstaged dialog). Other clicks land
    /// nowhere: the modal owns the board while open.
    fn click_planet_modal(&mut self, x: i32, y: i32) {
        match self.planet_board.planet_modal {
            Some(PlanetModal::QuitConfirm) => {
                let (ok_hit, cancel_hit) = self.question1_button_hits(x, y);
                if ok_hit {
                    self.cue_ui_effect(UiEffectId::DialogAccept);
                    self.confirm_quit();
                } else if cancel_hit {
                    self.cue_ui_effect(UiEffectId::DialogDecline);
                    self.cancel_quit_confirm();
                }
            }
            Some(PlanetModal::Options) => {
                self.click_options_dialog(x, y);
            }
            Some(PlanetModal::RelayDown) if self.relay_ok_hit(x, y) => {
                self.dismiss_relay_down_dialog();
            }
            Some(PlanetModal::RelayDown) => {}
            Some(PlanetModal::ChannelEnterRefused) if self.information_ok_hit(x, y) => {
                self.dismiss_channel_refusal_dialog();
            }
            Some(PlanetModal::ChannelEnterRefused) => {}
            None => {}
        }
    }

    /// One click inside the open options tab: the dialog changes its
    /// own settings and reports whether EXIT closed it, so the game
    /// keeps ownership of the modal.
    fn click_options_dialog(&mut self, x: i32, y: i32) {
        let volume_before = self.options_dialog.settings().bgm_music();
        let outcome = self.options_dialog.click(x, y);
        if outcome.close {
            self.planet_board.close_modal();
        }
        if let Some(effect) = outcome.effect {
            self.cue_ui_effect(effect);
        }
        // The dialog sits over the lobby: a BGMusic slider move must
        // re-cue the running scene track at its new gain without a
        // scene change. Other edits keep their existing paths.
        if self.options_dialog.settings().bgm_music() != volume_before {
            self.apply_scene_bgm();
        }
    }

    /// `Dialog_Question1` OK/CANCEL hits for both MESSAGE sheets:
    /// staged dialog rects when art is staged ([`dialog_rect_hit`]),
    /// the native fallback boxes otherwise ([`quit_fallback_rects`]).
    fn question1_button_hits(&self, x: i32, y: i32) -> (bool, bool) {
        let staged = self
            .planet_quit_art
            .as_ref()
            .filter(|art| art.has_figures());
        if let Some(art) = staged {
            (
                dialog_rect_hit(&art.placements, QUIT_OK_CODE, x, y),
                dialog_rect_hit(&art.placements, QUIT_CANCEL_CODE, x, y),
            )
        } else {
            let (_, ok, cancel) = quit_fallback_rects();
            (rect_hit(&ok, x, y), rect_hit(&cancel, x, y))
        }
    }

    /// MyRoom confirm OK/CANCEL hits: the staged dialog's `.bnd` rects
    /// when art is staged, the native fallback boxes otherwise. Both
    /// buttons are needed because CANCEL leaves the worn set alone.
    fn myroom_confirm_button_hits(&self, x: i32, y: i32) -> (bool, bool) {
        let staged_ok = self
            .relay_down_art
            .as_ref()
            .filter(|art| art.has_figures())
            .is_some_and(|art| dialog_rect_hit(&art.placements, INFORMATION_OK_CODE, x, y));
        (
            staged_ok || rect_hit(&information_ok_fallback_rect(), x, y),
            rect_hit(&information_cancel_fallback_rect(), x, y),
        )
    }

    /// One-OK Information sheet hit for `0X21200002`: its staged
    /// `.bnd` rect when art is staged, else the archive-less fallback
    /// plate. Shared by the relay notice and the Room fuse (#367).
    fn information_ok_hit(&self, x: i32, y: i32) -> bool {
        let staged = self.relay_down_art.as_ref().filter(|art| art.has_figures());
        if let Some(art) = staged {
            dialog_rect_hit(&art.placements, INFORMATION_OK_CODE, x, y)
        } else {
            rect_hit(&information_ok_fallback_rect(), x, y)
        }
    }

    /// Relay notice OK hit on the same Information sheet.
    fn relay_ok_hit(&self, x: i32, y: i32) -> bool {
        self.information_ok_hit(x, y)
    }

    /// Picked planet difficulty band, if any (paint/hit-test driver).
    #[must_use]
    pub fn planet_selection(&self) -> Option<super::side::PlanetBand> {
        self.planet_board.planet.band()
    }

    /// Last pressed promotion-carousel cell, if any (paint/click
    /// driver; `None` until a staged promo cell answers a click).
    #[must_use]
    pub fn planet_promo(&self) -> Option<PlanetPromo> {
        self.planet_board.planet_promo
    }

    /// Visible promo banner frame, 1-based (exe `this+0x80`; boot 1).
    #[must_use]
    pub fn planet_promo_index(&self) -> u32 {
        self.planet_board.planet_promo_carousel.index()
    }

    /// Whether the carousel rotation tick advances the banner (exe
    /// `this+0x90` nonzero; boot on).
    #[must_use]
    pub fn planet_promo_spinning(&self) -> bool {
        self.planet_board.planet_promo_carousel.spinning()
    }

    /// Staged promo banner frame count: the layers of the staged
    /// `IDC_IMAGE_SPLANET_PROMOTION` body (`0` while unstaged — the
    /// exe's wrap then lands on 0 and its refresh paints nothing).
    fn promo_frame_count(&self) -> u32 {
        self.scene_art(Screen::Planet)
            .and_then(|art| {
                art.placements
                    .iter()
                    .find(|placed| placed.code == PLANET_PROMO_IMAGE_CODE)
            })
            .and_then(|placed| placed.sprite.as_deref())
            .and_then(|sprite| {
                self.scene_art(Screen::Planet)
                    .and_then(|art| art.figures.get(sprite))
            })
            .map_or(0, |figure| u32::try_from(figure.len()).unwrap_or(0))
    }

    /// One carousel rotation step: advance a frame while spinning,
    /// hold while stopped (the tick body, VA `0x48e3b0`, minus the
    /// cadence gate). The clocked paint path owns the exe's
    /// `PLANET_PROMO_TICK_MS` cadence (`tick_planet_promo_at`, pulsed
    /// by the windowed heartbeat); this stays the driver-invoked
    /// single step.
    pub fn tick_planet_promo(&mut self) {
        let frames = self.promo_frame_count();
        self.planet_board.tick_promo(frames);
    }

    /// Clocked rotation advance: on the bare board while spinning,
    /// anchor the accumulator on the first paint, then step one
    /// banner frame per `PLANET_PROMO_TICK_MS` of frame time (the
    /// exe's per-frame update, VA `0x48e3b0`, fires the body on the
    /// same cadence). Covered boards, a cleared flag, and frameless
    /// boards never touch the accumulator, so the banner holds.
    /// Frame time is the paint seam's explicit instant (sample clock
    /// windowed, fixed clock on replays): no wall clock here.
    fn tick_planet_promo_at(&mut self, now_ms: u64) {
        if !self.bare_planet_board()
            || !self.planet_board.planet_promo_carousel.spinning()
            || self.promo_frame_count() == 0
        {
            return;
        }
        self.planet_board
            .tick_promo_clocked(now_ms, self.promo_frame_count());
    }

    /// Stage the worn figure the Room lobby paints in its avatar slot
    /// (`IDC_IMAGE_SROOM_AVATA`, code `0x13700013`). The binary stacks it
    /// from `avatar.opa` exactly like the Result figure; a missing
    /// archive stages nothing and the slot stays empty.
    pub fn load_room_avatar(&mut self, figure: AvatarFigure) -> &mut Self {
        self.room_avatar = Some(figure);
        self
    }

    /// Stage one pre-stacked waiting figure, keyed by seat (seat 0
    /// self, seats 1..=7 wire peers). Out-of-range seats are ignored;
    /// empty figures stay home (`None` keeps the slot empty).
    pub fn set_waiting_avatar(&mut self, seat: usize, figure: AvatarFigure) -> &mut Self {
        if figure.is_empty() {
            return self;
        }
        if let Some(slot) = self.waiting_figures.get_mut(seat) {
            *slot = Some(figure);
        }
        self
    }

    /// Staged waiting figure of one seat (`None` while unstaged).
    #[must_use]
    pub fn waiting_avatar(&self, seat: usize) -> Option<&AvatarFigure> {
        self.waiting_figures
            .get(seat)
            .and_then(|slot| slot.as_ref())
    }

    /// Room-panel figure when no per-seat figure covers the self seat.
    #[must_use]
    pub fn room_avatar(&self) -> Option<&AvatarFigure> {
        self.room_avatar.as_ref()
    }

    /// Whether any worn figure is available to a Waiting seat: the
    /// fetched-character seats or the lobby figure that stands in for
    /// seat 0. The item-composed figures replace the baked cover plate
    /// in the 7.55 capture (issue #336).
    #[must_use]
    fn has_staged_waiting_figure(&self) -> bool {
        self.waiting_figures.iter().any(Option::is_some) || self.room_avatar.is_some()
    }

    /// Stack one worn figure per occupied waiting seat from the
    /// `avatar.opa` archive plus the item table, through the shared
    /// [`load_worn_figure`] path (no fork: the same stacker the
    /// MyRoom figure and the Result banner use). The self seat wears
    /// the fetched character equipment, peers wear their wire
    /// `RoomMember.equipment`; `Any` gender wears the female parity
    /// (the connect slice's documented guess). Unresolvable pieces
    /// stay empty — one bad sprite never blanks a seat. Without a
    /// joined room this stages nothing. The production caller is
    /// [`Self::set_avatar_source`] plus the `set_joined_room`
    /// restage: the self arm fires only with a staged character
    /// (`set_myroom_character`), which the windowed entries fetch on
    /// channel login (ticket #58; the live-boot gate pins the fetch).
    /// Peers live; the self seat restages from live data on every join.
    pub fn stage_waiting_figures(&mut self, archive: &[u8], table: &AvatarItemTable) -> &mut Self {
        stage_seat_figures(
            &self.waiting,
            &self.myroom_character,
            archive,
            table,
            &mut self.waiting_figures,
        );
        self
    }

    /// Stage the avatar archive plus item table behind the per-seat
    /// worn figures (the launcher's `--avatar-opa` source); the seats
    /// restage at once through it and again on every later join, so
    /// peers wear their wire equipment as soon as the snapshot lands.
    /// The same table stages the MyRoom bag, gift, and info-plate
    /// name source: without it the avatar-room overlay's early return
    /// keeps every row blank live (ticket #199 diagnose leg — today
    /// only the shop catalog rode this landing, ticket #191).
    pub fn set_avatar_source(&mut self, archive: Vec<u8>, table: AvatarItemTable) -> &mut Self {
        self.set_decoded_avatar_source(&Arc::new(AvatarSource::with_table(archive, table)))
    }

    /// The decoded source staged by the last identity landing, if any.
    /// Callers compare `Arc` identity to pin that repeated landings
    /// reuse one decode rather than silently re-decoding the archive.
    #[must_use]
    pub fn staged_avatar_source(&self) -> Option<&Arc<AvatarSource>> {
        self.avatar_source.as_ref()
    }

    /// Stage a source decoded once by [`crate::avatar_source`]. The
    /// catalog, portraits, seats, and shop pane read the same shared
    /// bytes; no landing decodes the archive again.
    pub fn set_decoded_avatar_source(&mut self, source: &Arc<AvatarSource>) -> &mut Self {
        // The shop board rides the same `Itemdata_Korea.dat` table as
        // the avatar source (server-authoritative catalog join):
        // stage it here so the live board is never empty after the
        // avatar archive lands.
        self.shop.set_catalog(source.table());
        self.shop_item_portraits = Arc::clone(source.shop_portraits());
        self.myroom_items = Some(source.table().clone());
        self.avatar_source = Some(Arc::clone(source));
        self.restage_waiting_figures();
        self.restage_shop_avatar();
        self
    }

    /// Restage per-seat worn figures through the staged avatar source
    /// (no-op without one): called when the source lands and on every
    /// later join.
    fn restage_waiting_figures(&mut self) {
        let Some(source) = self.avatar_source.as_deref() else {
            return;
        };
        stage_seat_figures(
            &self.waiting,
            &self.myroom_character,
            source.archive(),
            source.table(),
            &mut self.waiting_figures,
        );
    }

    /// Committed equip send for the session bridge, if any (5004).
    /// One take sends once; the next apply replaces the queued send.
    pub fn take_equip_send(&mut self) -> Option<EquipItem> {
        self.outbox.take_equip_send()
    }

    /// Restore an equip body whose send failed so the session retries
    /// the same apply on the next paint.
    pub fn requeue_equip_send(&mut self, equip: EquipItem) {
        self.outbox.requeue_equip_send(equip);
    }

    /// Whether an equip send is queued for the session bridge.
    #[must_use]
    pub fn has_pending_equip_send(&self) -> bool {
        self.outbox.has_pending_equip_send()
    }

    /// Committed gift claim for the session bridge, if any (5023).
    /// One take sends once; the next MOVE replaces the queued claim.
    pub fn take_gift_claim(&mut self) -> Option<ClaimGift> {
        self.outbox.take_gift_claim()
    }

    /// Restage the worn figure after the equipment table changed
    /// (ticket #30 stale-figure leftover): the Room lobby slot and
    /// the Result banner re-stack from the staged avatar source like
    /// the channel-login staging does, and the waiting seats restage
    /// through it when a room is mounted. A missing source or an
    /// unstackable table keeps the old figures, never blanking them.
    fn restage_worn_figure(&mut self) {
        if let (Some(source), Some(character)) = (
            self.avatar_source.as_deref(),
            self.myroom_character.as_ref(),
        ) {
            let figure = load_worn_figure(
                source.archive(),
                source.table(),
                &character.equipment,
                character.gender == Gender::Male,
            );
            if !figure.is_empty() {
                self.room_avatar = Some(figure.clone());
                self.avatar = Some(figure);
            }
        }
        self.restage_waiting_figures();
        self.restage_shop_avatar();
    }

    /// Fold a successful `ClaimGift` 5024 reply into the staged room:
    /// the claimed gift leaves its box run, and an item gift lands its
    /// resource in the staged inventory (music gifts own no inventory
    /// row, so they only leave the box). Unknown gift ids change
    /// nothing. The session bridge owns the verdict; this is the
    /// staged-data fold it calls.
    pub fn apply_gift_claim_success(&mut self, gift_id: i32) {
        let Some(character) = self.myroom_character.as_mut() else {
            return;
        };
        if let Some(index) = character
            .item_gifts
            .iter()
            .position(|gift| gift.gift_id == gift_id)
        {
            let gift = character.item_gifts.remove(index);
            if !character.inventory.contains(&gift.item_id) {
                character.inventory.push(gift.item_id);
            }
            return;
        }
        if let Some(index) = character
            .music_gifts
            .iter()
            .position(|gift| gift.gift_id == gift_id)
        {
            character.music_gifts.remove(index);
        }
    }

    /// Open a side screen from a lobby; rejects other origins and
    /// remembers the lobby to return to. A tutorial visit also yields
    /// to an armed Loading gate, so a start never collides with the
    /// side visit. Entry cues the side screen's scene music (see
    /// [`SideScreen::bgm_cue`]); a rejected visit cues nothing.
    pub fn visit_side(&mut self, side: SideScreen) -> bool {
        if self.side.is_some() || !can_visit_side(self.flow.current(), side) {
            return false;
        }
        // Spec #313 story 20: the FIRSTSTEP arm calls `0x495110` with
        // no static refusal (`0x48fd20`, ev `ev_ac6983f7…`), so gate
        // precedence is ASSUMED until `N-LOADING` watches the pending
        // state at `0x478c50`/`0x477990`.
        if side == SideScreen::Tutorial && self.loading_gate_ready() {
            return false;
        }
        self.side_origin = Some(self.flow.current());
        self.side = Some(side);
        self.billing_failure_notice = false;
        self.mount_staged_side_art(side);
        if side == SideScreen::Tutorial {
            self.tutorial_clock_start_ms = None;
            self.tutorial_entered_wall = Some(Instant::now());
            self.tutorial_page = 0;
            self.apply_tutorial_ojm_cue();
            self.tutorial_key_lights.clear();
        } else {
            self.apply_bgm_cue(side.bgm_cue());
        }
        if side == SideScreen::MyRoom {
            // The wave-2 paired taps show no 5017/5018 on MyRoom or
            // Item Shop entry; the 7.55 builder has no call site.
            // No gift-list fetch is queued on entry (#857). Re-add it
            // only when a pinned cue names the send leg.
            // Entry tab word with a pending gift: the committed exe
            // trace `fixtures/input-trace/giftbox-claim.json` reaches
            // gift cell 0 (sequence 3) with no PRESENT BOX press, so
            // the recorded exe state has the gift side live right
            // after the Room -> MyRoom entry. The #807 pin gates gift
            // chrome behind the tab word `0x779924`; we therefore
            // default the word to the gift tab on entry when the
            // staged character carries a gift. CONTRADICTION
            // recorded, not resolved: the exe either auto-selects the
            // gift tab on entry-with-gift or hit-tests gift cells
            // word-independent. OPEN next step: the #530 per-slot/tab
            // sweep naming which (statics: who writes `0x779924` on
            // the MyRoom entry path).
            let gifts_pending = self.myroom_character.as_ref().is_some_and(|character| {
                !character.item_gifts.is_empty() || !character.music_gifts.is_empty()
            });
            if gifts_pending {
                self.myroom.show_lower_tab(MyRoomLowerTab::Gifts);
            }
        }
        if side == SideScreen::Shop {
            // The pane shows the equipped avatar on entry (a preview
            // never survives a leave — see `leave_side`). The BUYITEM
            // ladder reads the exe's bag-capacity global (`0x77cce4`);
            // stage the base 150 from the pinned max-bag notice so the
            // shortfall sheet can open on the live path (#867).
            self.stage_checkout_bag_capacity(super::side::SHOP_BASE_BAG_SLOTS);
            self.restage_shop_avatar();
        }
        if side == SideScreen::MusicShop {
            // Entry FUN_004c6d70 writes 0 into the TOP100 control
            // property at +0x20: no press and no ranking board (#827).
            self.music_shop.enter_music_shop();
        }
        true
    }

    /// Mount the declaration-staged art behind one side screen on
    /// entry (ticket #136): the live boot stages every Interface
    /// State into its full-screen scene slot, while the shots walk
    /// fills these side slots directly — both name the same State
    /// (`state_of_screen` == `state_of_side`), so mounting the
    /// staged scene art reproduces the walk's backdrop on the live
    /// path. Paint and click dispatch both read the side slots, so
    /// the mount fixes the black screen and the dead clicks
    /// together. Tutorial has no State scene slot: its Playing-archive
    /// bodies park in their own slot and mount here on entry. An
    /// unstaged slot leaves walk-staged slots untouched.
    fn mount_staged_side_art(&mut self, side: SideScreen) {
        if side == SideScreen::Tutorial {
            if let Some(art) = self.tutorial_art.clone() {
                self.side_placements = art.placements;
                self.side_figures = art.figures;
            }
            return;
        }
        if side == SideScreen::Payment {
            // The Cash Charge view sits on the Item Shop board in
            // the exe capture; only the plain billing stand-in uses
            // the Payment state sheets when the dialog is unstaged.
            let mounted = self
                .cash_charge_art
                .as_ref()
                .filter(|art| art.dialog.has_figures())
                .map(|art| (art.host.placements.clone(), art.host.figures.clone()))
                .or_else(|| {
                    self.payment_art
                        .as_ref()
                        .map(|art| (art.placements.clone(), art.figures.clone()))
                });
            if let Some((placements, figures)) = mounted {
                self.side_placements = placements;
                self.side_figures = figures;
            }
            return;
        }
        if let Some(slot) = side_scene_slot(side) {
            if let Some(art) = self.scene_art(slot).cloned() {
                self.side_placements = art.placements;
                self.side_figures = art.figures;
            }
        }
    }

    /// Return to the lobby that opened the side screen. The lobby
    /// is a scene entry again, so it re-cues its own scene music
    /// (see [`Screen::bgm_cue`]); a rejected return cues nothing.
    pub fn leave_side(&mut self) -> bool {
        let (Some(side), Some(origin)) = (self.side, self.side_origin) else {
            return false;
        };
        if !can_return_side(side, origin) {
            return false;
        }
        if side == SideScreen::Tutorial {
            self.tutorial_key_lights.clear();
            self.tutorial_clock_start_ms = None;
            self.tutorial_entered_wall = None;
            self.tutorial_page = 0;
        }
        self.billing_failure_notice = false;

        self.messenger_liveness_open = false;
        self.myroom_notice = None;
        self.myroom_confirm = None;

        self.myroom_notice = None;

        if side == SideScreen::Shop {
            // A preview never sticks past the shop: leaving reverts
            // to the equipped avatar (ticket #196).
            self.shop.clear_try_on();
            self.restage_shop_avatar();
            self.shop_charge_confirm_open = false;
            self.shop_charge_confirm_outcome = None;
        }
        self.side = None;
        self.side_origin = None;
        self.apply_bgm_cue(origin.bgm_cue());
        true
    }

