    /// Item-shop click through the control-code dispatch
    /// ([`shop_action_at`]): row toggles check the cart, `BUYITEM`
    /// opens the local web-purchase surface without a game opcode,
    /// both pagers step and hold at the ends, `ITEMPRE` previews the row
    /// good in the avatar pane, `ITEMBACK` reverts to the equipped
    /// avatar, and the gift buttons record a no-op (never a send).
    /// Staged placements only — unstaged clicks land nowhere. Only
    /// answers on the open shop side screen.
    pub fn click_shop(&mut self, x: i32, y: i32) {
        if self.side != Some(SideScreen::Shop) {
            return;
        }
        let Some(action) = shop_action_at(&self.side_placements, x, y) else {
            return;
        };
        let owned = self.shop.bag_goods(self.shop_inventory());
        let owned_len = owned.len();
        match action {
            ShopAction::BackToLobby => {
                // The tap leaves the side and emits the empty 5007;
                // the session owns the wire, the shell owns the return.
                if self.leave_side() {
                    self.outbox.pending_exit_shop = Some(o2jam_net::shop::ExitShop);
                }
            }
            ShopAction::GoMyRoom => {
                // Static arm `0x14200003` (`ev_f3ad15be…`): screen
                // change only. The session outbox stays untouched —
                // no 5007 and no invented opcode on this arm. The
                // tapped destination frame is the OPEN next step.
                let _ = self.leave_side();
            }
            ShopAction::OpenCashCharge => {
                // The charge plate leaves the shop board and opens
                // the Cash Charge view from the same lobby (b8).
                if self.leave_side() {
                    self.visit_side(SideScreen::Payment);
                }
            }
            ShopAction::GiftRow(_) => self.record_shop_gift_noop(action),
            ShopAction::GiftCart => {
                // The web-only gift record stays; the static arm also
                // sets mode 2 and sends 5015 when its ladder passes.
                self.record_shop_gift_noop(action);
                self.run_checkout(super::side::CheckoutMode::Gift, owned_len);
            }
            ShopAction::TryOn(slot) => {
                // One ITEMPRE press drives both browse surfaces: the
                // avatar-pane figure (restage) and the comment preview.
                self.shop.apply_action(action, &owned);
                self.shop.select_preview(slot);
                self.restage_shop_avatar();
            }
            ShopAction::RevertTryOn => {
                // Exe arm `0x1420006c`: FUN_00540500, then a full
                // 0x2190-byte copy from global `0x77cd00` into the
                // local avatar block and a repaint. The snapshot was
                // taken on character staging, so every slot reverts.
                self.shop.apply_action(action, &owned);
                self.shop.clear_preview();
                if let (Some(block), Some(character)) =
                    (self.equipped_block.as_ref(), self.myroom_character.as_mut())
                {
                    block.restore_equipment(character);
                }
                self.restage_shop_avatar();
            }
            ShopAction::CartBuy => {
                // #867: BUYITEM's O2CASH shortfall arm posts the native
                // type-2 MESSAGE sheet (exe VA `0x499f43`, caption
                // `0x648b38`). The Cash Charge web view belongs to the
                // CASHFILLUP arm, so no web surface opens here.
                self.shop.apply_action(action, &owned);
                self.run_checkout(super::side::CheckoutMode::Buy, owned_len);
                if self.shop.checkout_notice()
                    == Some(super::side::CheckoutNotice::InsufficientCash)
                {
                    self.shop_charge_confirm_open = true;
                    self.shop_charge_confirm_outcome = None;
                }
            }
            ShopAction::OpenMessenger => {
                // `FUN_004a3060(0)` advances the staged lamp rects and
                // the global branch posts a notice. No local Messenger
                // backend or wire opcode is pinned (#648 stays OPEN).
                self.shop.apply_action(action, &owned);
            }
            ShopAction::SortBag => {
                // Static arm `0x142000b7` (file `0x9bfa8`): the sort
                // press itself stages nothing, but queues the empty
                // 5038. The session owns the wire; live no-wire tap
                // stays recorded beside the pin.
                self.shop.apply_action(action, &owned);
                self.outbox.pending_refresh_bag = Some(RefreshBag);
            }
            _ => {
                self.shop.apply_action(action, &owned);
            }
        }
    }

    /// Run the BUYITEM/GIFTITEM ladder and queue its static 5015
    /// send when every staged gate passes. The web surface and the
    /// gift no-op record stay as the live-observed arms.
    fn run_checkout(&mut self, mode: super::side::CheckoutMode, owned_len: usize) {
        self.shop.stage_checkout_bag_used(owned_len);
        if self.shop.approve_checkout(mode, &self.wallet) {
            self.outbox.pending_start_payment = Some(StartPayment);
        }
    }

    /// Record one staged shop gift press: the control id plus the
    /// next evidence step. Queues nothing — gift send has no TCP
    /// shape on 7.55 (web-only `gift_input.aspx`, `docs/gifts.md`).
    fn record_shop_gift_noop(&mut self, action: ShopAction) {
        let id = match action {
            ShopAction::GiftRow(slot) => SHOP_ITEMGIFT_IDS
                .get(slot)
                .copied()
                .unwrap_or(SHOP_GIFTITEM_ID),
            _ => SHOP_GIFTITEM_ID,
        };
        self.shop_gift_noop = Some(ShopGiftNoop {
            id,
            next_step: SHOP_GIFT_NEXT_STEP,
        });
    }

    /// Last recorded shop gift no-op (`None` until a gift button
    /// answers).
    #[must_use]
    pub fn shop_gift_noop(&self) -> Option<ShopGiftNoop> {
        self.shop_gift_noop
    }

