    /// Waiting art with the master's START body carrying three distinct
    /// records: record 0 red (rest), record 1 green (hover), record 2
    /// blue (the armed face — `Wait_Start.ojs` carries 3 raw records and
    /// the exe's kind-`0x2000` arm paints absolute frame 3).
    fn waiting_three_record_start_game(member_id: u8) -> ScreenGame {
        use crate::avatar::{AvatarFigure, FigureLayer, ScenePlacement};
        use o2jam_render::Rgb555Image;
        let record = |word: [u8; 2]| {
            let mut figure = AvatarFigure::default();
            figure.push_layer(FigureLayer {
                image: Rgb555Image::decode(&word, 1, 1).unwrap(),
                dx: 0,
                dy: 0,
                colorkey: 0xFFFF,
            });
            figure
        };
        let mut body = record([0x00, 0x7C]);
        body.push_layer(FigureLayer {
            image: Rgb555Image::decode(&[0xE0, 0x03], 1, 1).unwrap(),
            dx: 0,
            dy: 0,
            colorkey: 0xFFFF,
        });
        body.push_layer(FigureLayer {
            image: Rgb555Image::decode(&[0x1F, 0x00], 1, 1).unwrap(),
            dx: 0,
            dy: 0,
            colorkey: 0xFFFF,
        });
        let mut game = ScreenGame::new();
        let mut room = waiting_room();
        room.member_id = member_id;
        // The local seat is the joined member, marked ready: the word
        // the READY face follows (self ready byte `0x77cd32`).
        let local = room.slots[0].member.clone().expect("staged member");
        room.slots = (0..=member_id)
            .map(|index| RoomSlot {
                index,
                state_code: 1,
                member: (index == member_id).then(|| local.clone()),
            })
            .collect();
        game.set_joined_room(room);
        walk_to_waiting(&mut game);
        let confirm = if member_id == 0 {
            "IDC_BUTTON_SWAIT_START"
        } else {
            "IDC_BUTTON_SWAIT_READY"
        };
        game.load_scene(
            Screen::Waiting,
            vec![ScenePlacement {
                role: PlacementRole::Single,
                id: confirm.to_owned(),
                code: 0,
                sprite: Some("Wait_Start.ojs".to_owned()),
                rect: Rect {
                    x: 10,
                    y: 10,
                    w: 4,
                    h: 4,
                },
            }],
            std::collections::HashMap::from([("Wait_Start.ojs".to_owned(), body)]),
        );
        game
    }

    /// Pixel the confirm body paints at its rect origin.
    fn painted_confirm_pixel(game: &mut ScreenGame) -> u32 {
        let mut buf = vec![0u32; 800 * 600];
        game.paint_at(
            &mut Frame {
                buf: &mut buf,
                w: 800,
                h: 600,
            },
            0,
        );
        buf[10 * 800 + 10]
    }

    /// Solo room whose only seat is not 0, announced as master by a
    /// 3007 handoff. Both role-owned controls carry three synthetic
    /// records (rest red, hover green, armed blue) at distinct rects.
    fn waiting_solo_promoted_master_game() -> ScreenGame {
        use crate::avatar::{AvatarFigure, FigureLayer, ScenePlacement};
        use o2jam_render::Rgb555Image;
        let record = |word: [u8; 2]| {
            let mut figure = AvatarFigure::default();
            figure.push_layer(FigureLayer {
                image: Rgb555Image::decode(&word, 1, 1).unwrap(),
                dx: 0,
                dy: 0,
                colorkey: 0xFFFF,
            });
            figure
        };
        let mut body = record([0x00, 0x7C]);
        body.push_layer(FigureLayer {
            image: Rgb555Image::decode(&[0xE0, 0x03], 1, 1).unwrap(),
            dx: 0,
            dy: 0,
            colorkey: 0xFFFF,
        });
        body.push_layer(FigureLayer {
            image: Rgb555Image::decode(&[0x1F, 0x00], 1, 1).unwrap(),
            dx: 0,
            dy: 0,
            colorkey: 0xFFFF,
        });
        let mut room = waiting_room();
        room.member_id = 1;
        room.team = 1;
        room.user_count = 1;
        let mut local = room.slots[0].member.clone().expect("staged member");
        local.master = true;
        room.slots = vec![RoomSlot {
            index: 1,
            state_code: 1,
            member: Some(local),
        }];
        let mut game = ScreenGame::new();
        game.set_joined_room(room);
        game.promote_waiting_master(1);
        walk_to_waiting(&mut game);
        let placement = |id: &str, sprite: &str, x: i32| ScenePlacement {
            role: PlacementRole::Single,
            id: id.to_owned(),
            code: 0,
            sprite: Some(sprite.to_owned()),
            rect: Rect {
                x,
                y: 10,
                w: 4,
                h: 4,
            },
        };
        game.load_scene(
            Screen::Waiting,
            vec![
                placement("IDC_BUTTON_SWAIT_START", "Wait_Start.ojs", 10),
                placement("IDC_BUTTON_SWAIT_READY", "Wait_Ready.ojs", 20),
            ],
            HashMap::from([
                ("Wait_Start.ojs".to_owned(), body.clone()),
                ("Wait_Ready.ojs".to_owned(), body),
            ]),
        );
        game
    }

    /// Ticket #561: a solo master's START face must follow the same
    /// role the session uses for the START send. The exe's `+0x30` role
    /// flag (files `0xae38e`/`0xae805`) picks the control, not the seat
    /// index: a room handed over to seat 1 still enables START.
    ///
    /// Live chain: `main.rs::run_play` -> `OnlineSession::paint` (3007
    /// promotion) -> `ScreenGame::promote_waiting_master` ->
    /// `ScreenGame::paint` -> `paint_waiting_scene_with_master_seat` ->
    /// `paint_waiting_confirm_face`. Seam: the synthetic three-record
    /// art is the whole face contract; archives absent -> N/A.
    #[test]
    fn solo_promoted_master_paints_the_start_face_not_the_guest_ready_face() {
        let mut game = waiting_solo_promoted_master_game();
        assert!(game.is_room_master());
        assert_eq!(game.start_gate_verdict(), StartGateVerdict::Startable);
        assert_eq!(game.press_start(), StartRequest::StartGame);
        assert!(game.waiting_confirm_armed());

        let frame = paint_waiting_frame(&mut game, 800, 600);
        assert_eq!(
            frame[10 * 800 + 10],
            pack_xrgb(0, 0, 255),
            "the promoted solo master paints the armed START record"
        );
        assert_eq!(
            frame[10 * 800 + 20],
            0,
            "the guest READY control stays out of the master's face"
        );
    }

    /// Ticket #561: the -1/-2/-3/-4/-5 verdict arms (VA `0x4b5560`)
    /// all read an occupied *peer* seat. A solo room has none, so its
    /// own unready byte, missing chart byte, or lone team cannot close
    /// START; the server's 4011 answer owns the local-song refusal.
    ///
    /// Live chain: `main.rs::run_play` -> `OnlineSession::menu_key`
    /// (Waiting Confirm) -> `confirm_master_start` ->
    /// `ScreenGame::press_start` -> `start_gate_verdict`.
    /// Seam suffices: the verdict is a pure function of the staged
    /// room; the paint face is pinned by the guard above.
    #[test]
    fn solo_master_gate_has_no_peer_only_verdict_arm() {
        let mut game = ScreenGame::new();
        game.set_joined_room(waiting_room());
        walk_to_waiting(&mut game);
        for state in [
            o2jam_net::MusicState::NoMusic.code(),
            o2jam_net::MusicState::NoAccess.code(),
            o2jam_net::MusicState::Downloading.code(),
        ] {
            let room = game.waiting.as_mut().expect("joined room");
            room.team = 1;
            let seat = room.slots[0].member.as_mut().expect("solo seat");
            seat.ready = false;
            seat.music_state = state;
            assert_eq!(game.start_gate_verdict(), StartGateVerdict::Startable);
            assert_eq!(game.press_start(), StartRequest::StartGame);
            assert!(game.waiting_confirm_armed());
        }
    }

    #[test]
    fn waiting_start_arm_paints_the_third_record() {
        // Ticket #284: the exe swaps the START body to absolute frame 3
        // (the third record, `docs/room-enums.md:145`: frame n paints
        // record n-1) through the per-control press state word setter
        // `0x4f72b0` and the Waiting update's cached re-assert (file
        // `0xb29b0`-`0xb29e5`). Live chain: `main::run_online` ->
        // `Shell::run` -> `Session::paint` -> `ScreenGame::paint` ->
        // `paint_waiting` -> `paint_waiting_scene` ->
        // `paint_waiting_confirm_face`; the arm arrives from
        // `OnlineSession::confirm_master_start` ->
        // `ScreenGame::arm_waiting_start`.
        let mut game = waiting_three_record_start_game(0);
        assert_eq!(
            painted_confirm_pixel(&mut game),
            pack_xrgb(255, 0, 0),
            "a master with no request standing paints the rest record"
        );
        game.arm_waiting_start();
        assert_eq!(
            painted_confirm_pixel(&mut game),
            pack_xrgb(0, 0, 255),
            "the standing start request paints the third record"
        );
    }

    #[test]
    fn waiting_guest_ready_arm_paints_the_third_record() {
        // The guest face follows the local seat's ready byte: the
        // seat-ready update arms frame 3 while ready and clears it with
        // an explicit rest frame when not (VA `0x4b5850`, file
        // `0xb590b`-`0xb594f`). Live chain: `main::run_online` ->
        // `Shell::run` -> `Session::paint` -> `ScreenGame::paint` ->
        // `paint_waiting` -> `paint_waiting_scene` ->
        // `paint_waiting_confirm_face`; the ready flag arrives from
        // `OnlineSession::confirm_guest_ready` ->
        // `ScreenGame::set_member_ready`.
        let mut game = waiting_three_record_start_game(1);
        assert_eq!(
            painted_confirm_pixel(&mut game),
            pack_xrgb(0, 0, 255),
            "a ready guest paints the third record"
        );
        game.set_member_ready(1, false);
        assert_eq!(
            painted_confirm_pixel(&mut game),
            pack_xrgb(255, 0, 0),
            "an un-ready guest returns to the rest record"
        );
    }

