    #[test]
    fn hovered_room_control_resolves_the_staged_chrome_button() {
        // The pointer is the shared hover source (ticket #26 consumes
        // it for the planet board); the room resolver maps it onto
        // staged chrome the same way clicks resolve.
        let mut game = hover_room_game();
        assert_eq!(game.hovered_room_control(), None);
        game.ingest_snapshot(&InputSnapshot::motion_to(752, 581));
        assert_eq!(
            game.hovered_room_control().map(|control| control.code),
            Some(ROOM_BACK_BUTTON_CODE)
        );
        assert_eq!(
            game.hovered_room_control().map(|control| control.id),
            Some(ROOM_BACK_BUTTON_ID)
        );
        game.ingest_snapshot(&InputSnapshot::motion_to(10, 10));
        assert_eq!(game.hovered_room_control(), None);
    }

    #[test]
    fn hovered_room_control_clears_off_the_room_scene() {
        // Leaving the lobby drops hover even though the pointer still
        // sits inside the button rect (BACK answers the click).
        let mut game = hover_room_game();
        game.ingest_snapshot(&InputSnapshot::motion_to(752, 581));
        assert_eq!(
            game.hovered_room_control().map(|control| control.code),
            Some(ROOM_BACK_BUTTON_CODE)
        );
        game.ingest_snapshot(&InputSnapshot::click_at(752, 581));
        assert_eq!(game.screen(), Screen::Channel);
        assert_eq!(game.hovered_room_control(), None);
    }

    #[test]
    fn hovered_room_button_repaints_its_first_frame() {
        // The exe repaints the hovered button at full body frame 0
        // over the stacked rest paint (`docs/hover.md` 2026-11-10
        // sweep); leaving the control restores the rest paint.
        let mut game = hover_room_game();
        let rest = pack_xrgb(0x00, 0xFF, 0x00);
        let hover = pack_xrgb(0x00, 0x00, 0xFF);
        assert_eq!(room_pixel(&mut game, 752, 581), rest);
        game.ingest_snapshot(&InputSnapshot::motion_to(752, 581));
        assert_eq!(room_pixel(&mut game, 752, 581), hover);
        game.ingest_snapshot(&InputSnapshot::motion_to(10, 10));
        assert_eq!(room_pixel(&mut game, 752, 581), rest);
    }

    #[test]
    fn room_messenger_hover_repaints_the_pinned_body_frame() {
        // Spec #315 story M3: the Room MESSENGER button hover repaints
        // `Btn_Messenger.ojs` frame 0 on rect `627,571-662,590`.
        // EXE pins `docs/hover.md:120` (hover frame fd9a61c9…20d vs
        // rest 35b4d5d4…868, 434 changed px); the sweep is a frame
        // pin, not a fresh capture claim. Live chain: boot -> Channel
        // -> Room -> pointer snapshot -> `hovered_room_control` ->
        // `paint_room` -> `paint_room_scene_with_hover` ->
        // `paint_room_hover` frame 0. Synthetic two-frame body keeps
        // the guard data-independent (CI has no archives).
        use crate::screens::messenger::MessengerHost;
        let code = MessengerHost::Room.control_code();
        assert_eq!(code, 0x1320_0048, "pinned Room MESSENGER code");
        let rect = Rect {
            x: 627,
            y: 571,
            w: 35,
            h: 19,
        };
        let mut game = room_lobby_with_placements(vec![(code, "IDC_BUTTON_SROOM_MESSENGER", rect)]);
        game.load_scene(
            Screen::Room,
            vec![ScenePlacement {
                role: PlacementRole::Single,
                id: "IDC_BUTTON_SROOM_MESSENGER".to_owned(),
                code,
                sprite: Some("Btn_Messenger.ojs".to_owned()),
                rect,
            }],
            HashMap::from([(
                "Btn_Messenger.ojs".to_owned(),
                chrome_two_layer_figure(35, 19),
            )]),
        );
        let rest = pack_xrgb(0x00, 0xFF, 0x00);
        let hover = pack_xrgb(0x00, 0x00, 0xFF);
        assert_eq!(room_pixel(&mut game, 644, 580), rest);
        game.ingest_snapshot(&InputSnapshot::motion_to(644, 580));
        assert_eq!(
            game.hovered_room_control().map(|control| control.code),
            Some(code),
            "the pinned rect names the MESSENGER chrome"
        );
        assert_eq!(
            room_pixel(&mut game, 644, 580),
            hover,
            "hover repaints frame 0"
        );
        game.ingest_snapshot(&InputSnapshot::motion_to(10, 10));
        assert_eq!(
            room_pixel(&mut game, 644, 580),
            rest,
            "unhover restores rest"
        );
    }

    #[test]
    fn firststep_hover_repaints_its_staged_body_frame_on_the_room_board() {
        // Spec #313 WAVE5 row: the Room FIRSTSTEP chrome
        // `0x13200032` repaints `Room_FirstStep.ojs` body frame 0 under
        // the pointer. EXE pin `docs/hover.md:111`: rest matches
        // neither frame (31% / 22%), hover matches frame 0 (100%),
        // rect `660,1-718,32`, hover capture hash `36575039…4009e`.
        // Live chain: boot -> Channel -> Room -> pointer snapshot ->
        // `hovered_room_control` -> `paint_room` ->
        // `paint_room_scene_with_hover` -> `paint_room_hover` frame 0.
        // A two-record synthetic body keeps the guard data-independent.
        let rect = Rect {
            x: 660,
            y: 1,
            w: 58,
            h: 31,
        };
        let mut game =
            room_lobby_with_placements(vec![(0x1320_0032, "IDC_BUTTON_SROOM_FIRSTSTEP", rect)]);
        game.load_scene(
            Screen::Room,
            vec![ScenePlacement {
                role: PlacementRole::Single,
                id: "IDC_BUTTON_SROOM_FIRSTSTEP".to_owned(),
                code: 0x1320_0032,
                sprite: Some("Room_FirstStep.ojs".to_owned()),
                rect,
            }],
            HashMap::from([(
                "Room_FirstStep.ojs".to_owned(),
                chrome_two_layer_figure(58, 31),
            )]),
        );
        let rest = pack_xrgb(0x00, 0xFF, 0x00);
        let hover = pack_xrgb(0x00, 0x00, 0xFF);
        assert_eq!(room_pixel(&mut game, 689, 16), rest);
        game.ingest_snapshot(&InputSnapshot::motion_to(689, 16));
        assert_eq!(
            game.hovered_room_control().map(|control| control.code),
            Some(0x1320_0032),
            "B7's FIRSTSTEP aim resolves the staged chrome"
        );
        assert_eq!(
            room_pixel(&mut game, 689, 16),
            hover,
            "hover paints body frame 0"
        );
        game.ingest_snapshot(&InputSnapshot::motion_to(10, 10));
        assert_eq!(
            room_pixel(&mut game, 689, 16),
            rest,
            "unhover restores the rest body"
        );
    }

    #[test]
    fn hovered_room_button_repaints_on_an_empty_room_list() {
        // The exe arms chrome hover on an empty live room — every
        // `docs/hover.md` sweep row shows the six empty row panels
        // while BACK/CREATE/QUICKJOIN still repaint on hover — so the
        // empty-list paint arm must repaint the hovered frame too,
        // not only the non-empty-list `paint_room_scene` arm.
        let mut game = hover_empty_room_game();
        let rest = pack_xrgb(0x00, 0xFF, 0x00);
        let hover = pack_xrgb(0x00, 0x00, 0xFF);
        assert_eq!(room_pixel(&mut game, 752, 581), rest);
        game.ingest_snapshot(&InputSnapshot::motion_to(752, 581));
        assert_eq!(
            game.hovered_room_control().map(|control| control.code),
            Some(ROOM_BACK_BUTTON_CODE)
        );
        assert_eq!(room_pixel(&mut game, 752, 581), hover);
        game.ingest_snapshot(&InputSnapshot::motion_to(10, 10));
        assert_eq!(room_pixel(&mut game, 752, 581), rest);
    }

    #[test]
    fn empty_room_list_hides_the_authored_row_template_clones() {
        // Live caller chain: main.rs::run_online/run_play -> 2003 reply ->
        // ScreenGame::set_rooms -> ScreenGame::paint_room ->
        // paint_room_scene_with_hover -> clone_instance_live. The
        // `SET 0x11` row template clones carry the sheet's example ink
        // (EX05/NEW/3KEY/...); with no live rows the exe shows none of
        // it. Synthetic one-pixel clone, no game data.
        let mut game = hover_empty_room_game();
        game.load_scene(
            Screen::Room,
            vec![
                ScenePlacement {
                    role: PlacementRole::Single,
                    id: "IDC_BUTTON_SROOM_EXBUTTON1".to_owned(),
                    code: 0x1301_201B,
                    sprite: Some("Room_Panel.ojs".to_owned()),
                    rect: Rect {
                        x: 26,
                        y: 82,
                        w: 288,
                        h: 91,
                    },
                },
                ScenePlacement {
                    role: PlacementRole::Clone,
                    id: "IDC_BUTTON_SROOM_EXBUTTON1".to_owned(),
                    code: 0x1350_002E,
                    sprite: Some("Room_Template.ojs".to_owned()),
                    rect: Rect {
                        x: 100,
                        y: 100,
                        w: 8,
                        h: 8,
                    },
                },
            ],
            HashMap::from([
                ("Room_Panel.ojs".to_owned(), solid_figure(288, 91, 0x03E0)),
                ("Room_Template.ojs".to_owned(), solid_figure(8, 8, 0x001F)),
            ]),
        );
        assert!(game.listed_rooms().is_empty());
        let panel_ink = pack_xrgb(0x00, 0xFF, 0x00);
        let template_ink = pack_xrgb(0x00, 0x00, 0xFF);
        assert_eq!(
            room_pixel(&mut game, 60, 100),
            panel_ink,
            "the empty row panels themselves stay painted"
        );
        assert_ne!(
            room_pixel(&mut game, 102, 102),
            template_ink,
            "the empty list must not paint the authored template clone"
        );
        game.set_rooms(two_rooms());
        assert_eq!(
            room_pixel(&mut game, 60, 100),
            panel_ink,
            "the row panels stay painted with live rows too"
        );
        assert_eq!(
            room_pixel(&mut game, 102, 102),
            template_ink,
            "one live row makes the first template clone paint"
        );
    }

    #[test]
    fn active_room_control_ignores_hover() {
        // SHOW_ALLMODE rests at frame 1 and the rig pins no change on
        // hover (`docs/hover.md`): hovering the active filter resolves
        // to no control, so the frame stays byte-identical instead of
        // taking the frame-0 repaint.
        let mut game = hover_room_lobby();
        let rect = Rect {
            x: 112,
            y: 22,
            w: 90,
            h: 41,
        };
        game.load_scene(
            Screen::Room,
            vec![ScenePlacement {
                role: PlacementRole::Single,
                id: "IDC_BUTTON_SROOM_SHOW_ALLMODE".to_owned(),
                code: 0x1320_1003,
                sprite: Some("Room_Btn_Show_AllMode.ojs".to_owned()),
                rect,
            }],
            HashMap::from([(
                "Room_Btn_Show_AllMode.ojs".to_owned(),
                chrome_two_layer_figure(90, 41),
            )]),
        );
        let mut rest = vec![0u32; 800 * 600];
        game.paint_at(
            &mut Frame {
                buf: &mut rest,
                w: 800,
                h: 600,
            },
            0,
        );
        game.ingest_snapshot(&InputSnapshot::motion_to(150, 40));
        assert_eq!(game.hovered_room_control(), None);
        let mut hovered = vec![0u32; 800 * 600];
        game.paint_at(
            &mut Frame {
                buf: &mut hovered,
                w: 800,
                h: 600,
            },
            0,
        );
        assert_eq!(rest, hovered, "active filter repaints nothing on hover");
    }

