    /// Ticket #794: the item record's `+0x18` byte names the well,
    /// not the equipment word's ordinal. A non-sequential byte must
    /// ink its own well and leave the ordinal well blank.
    #[test]
    fn myroom_record_slot_byte_selects_the_well_not_the_equipment_ordinal() {
        // Live caller chain: S2C 2001 equipment -> set_myroom_character
        // -> paint_at -> paint_side -> paint_myroom_overlay ->
        // paint_myroom_slot_icons. The join is the pinned state-entry
        // rule (FUN_004a3730, EV ev_004adf63…), not a UI guess.
        use super::super::side::MYROOM_SLOT_IMAGE_FIRST_CODE;
        const WELL: u8 = 3;
        const ITEM_ID: i32 = 401;
        let table = o2jam_file::AvatarItemTable {
            rows: vec![o2jam_file::AvatarItemRow {
                item_id: u32::try_from(ITEM_ID).expect("fixture id"),
                item_type: 2,
                price: 100,
                params: [0, 0, u32::from(WELL) << 24, 0],
                flags: (0, 0),
                name: "NonSequentialGear".to_owned(),
                description: String::new(),
                sprites: Vec::new(),
            }],
        };
        let mut character = myroom_test_character(Vec::new());
        character.equipment[0] = ITEM_ID;
        let mut game = ScreenGame::new();
        walk_to_lobby(&mut game, Screen::Room);
        game.set_myroom_items(table);
        game.set_myroom_character(character);
        Arc::make_mut(&mut game.shop_item_portraits).insert(
            u32::try_from(ITEM_ID).expect("fixture id"),
            solid_test_figure([0x00, 0x7C]),
        );
        let well_placement = |well: u8| ScenePlacement {
            role: PlacementRole::Single,
            id: format!("IDC_IMAGE_SMYROOM_WELL{well}"),
            code: MYROOM_SLOT_IMAGE_FIRST_CODE + u32::from(well),
            sprite: None,
            rect: Rect {
                x: 40 + i32::from(well) * 60,
                y: 60,
                w: 48,
                h: 48,
            },
        };
        game.load_side_scene(
            vec![well_placement(0), well_placement(WELL)],
            HashMap::new(),
        );
        assert!(game.visit_side(SideScreen::MyRoom));
        let mut buf = vec![0u32; 800 * 600];
        game.paint_at(
            &mut Frame {
                buf: &mut buf,
                w: 800,
                h: 600,
            },
            0,
        );
        let inked = |well: u8| {
            let x0 = 40 + i32::from(well) * 60;
            (60..108).any(|y| (x0..x0 + 48).any(|x| buf[y * 800 + x as usize] != 0))
        };
        assert!(inked(WELL), "the record slot byte inks its own well");
        assert!(!inked(0), "the equipment ordinal no longer picks the well");
    }

    /// Ticket #199 breathe leg: the staged MyRoom figure must idle-
    /// breathe on the paint clock — one frame per 12-frame body per
    /// tick, single-frame bodies every paint (the #193 per-run rule
    /// through the MyRoom path).
    #[test]
    fn myroom_figure_breathes_on_the_paint_clock() {
        // Live caller chain:
        //   main.rs::run_play -> GameLoop paint -> ScreenGame::paint_at
        //   -> paint_side -> paint_myroom_figure
        //   -> AvatarFigure::paint_visible_centered(now_ms)
        //   -> avatar_animation_phase(now_ms) selects the phase and the
        //   run frame (66 ms step, pinned in `docs/equip.md`).
        // Archives absent -> N/A (synthetic layers, no archive read).
        use crate::avatar::{FigureLayer, AVATAR_BREATHING_TICK_MS};
        use o2jam_render::Rgb555Image;
        let layer = |word: u16, dx: i32| FigureLayer {
            image: Rgb555Image::decode(&word.to_le_bytes(), 1, 1).unwrap(),
            dx,
            dy: 0,
            colorkey: 0x0000,
        };
        let mut figure = AvatarFigure::default();
        for frame in 0..12u16 {
            figure.push_layer(layer(0x0001 + frame, i32::from(frame)));
        }
        let mut single = AvatarFigure::default();
        single.push_layer(layer(0x7FFF, 12));
        figure.push_body(single);
        let mut game = ScreenGame::new();
        walk_to_lobby(&mut game, Screen::Room);
        game.load_room_avatar(figure);
        use super::super::side::MYROOM_AVATAR_CODE;
        game.load_scene(
            Screen::Myroom,
            vec![ScenePlacement {
                role: PlacementRole::Single,
                id: String::new(),
                code: MYROOM_AVATAR_CODE,
                sprite: None,
                rect: Rect {
                    x: 300,
                    y: 200,
                    w: 100,
                    h: 160,
                },
            }],
            HashMap::new(),
        );
        assert!(game.visit_side(SideScreen::MyRoom));
        let paint = |game: &mut ScreenGame, now_ms: u64| {
            let mut buf = vec![0u32; 800 * 600];
            game.paint_at(
                &mut Frame {
                    buf: &mut buf,
                    w: 800,
                    h: 600,
                },
                now_ms,
            );
            buf
        };
        let inked_x = |buf: &[u32]| {
            (300..400)
                .filter(|&x| (200..360).any(|y| buf[y * 800 + x] != 0))
                .collect::<Vec<_>>()
        };
        let parked = inked_x(&paint(&mut game, 0));
        let ticked = inked_x(&paint(&mut game, AVATAR_BREATHING_TICK_MS));
        assert!(
            !parked.is_empty() && !ticked.is_empty(),
            "the staged figure inks its slot on both paints"
        );
        assert_ne!(
            parked, ticked,
            "the paint clock advances the 12-frame run's selected frame"
        );
        assert!(
            parked.iter().any(|x| ticked.contains(x)),
            "the single-frame body paints on every paint"
        );
    }

    #[test]
    fn myroom_money_captions_read_the_single_wallet() {
        // Live caller chain (feed):
        //   main.rs::run_play -> setup_online -> stage_online_identity
        //   -> ScreenGame::set_myroom_character -> WalletState::apply_character_cash.
        // Live caller chain (read):
        //   OnlineSession::paint (GameLoop) -> ScreenGame::paint_myroom_overlay
        //   -> myroom_wallet_captions.
        // Pure shell state: no archives read, so no CI skip.
        use super::super::side::{
            MYROOM_ITEMCASH_CODE, MYROOM_MGAME_MONEY_CODE, MYROOM_MUSICCASH_CODE,
            MYROOM_O2CASH_CODE, MYROOM_O2JAM_MONEY_CODE,
        };
        let mut game = ScreenGame::new();
        game.set_myroom_character(CharacterInfo {
            gem: 15_527,
            o2_cash: 500,
            music_cash: 120,
            item_cash: 340,
            cash_point: 22,
            ..CharacterInfo::default()
        });
        assert_eq!(game.wallet().gem, Some(15_527));
        assert_eq!(game.wallet().o2_cash, Some(500));
        assert_eq!(game.wallet().music_cash, Some(120));
        assert_eq!(game.wallet().item_cash, Some(340));
        assert_eq!(game.wallet().cash_point, Some(22));
        let captions = game.myroom_money_captions();
        let caption = |code: u32| {
            captions
                .iter()
                .find(|(candidate, _)| *candidate == code)
                .map(|(_, text)| text.as_str())
        };
        assert_eq!(caption(MYROOM_O2CASH_CODE), Some("500"));
        assert_eq!(caption(MYROOM_MUSICCASH_CODE), Some("120"));
        assert_eq!(caption(MYROOM_ITEMCASH_CODE), Some("340"));
        // G cell bnd rect (685,421)-(780,434): the exe's G 15527 and
        // G 626 frames match the 5029 gem words a73c0000 / 72020000.
        assert_eq!(caption(MYROOM_MGAME_MONEY_CODE), Some("15527"));
        // W cell reads the other settled 5029 word: file `0x163900`
        // routes it to the wallet cash slot (`docs/shop-buy.md`).
        assert_eq!(caption(MYROOM_O2JAM_MONEY_CODE), Some("22"));
    }

    #[test]
    fn myroom_screen_cluster_pins_clicks_captions_and_painted_pixels() {
        // Live caller chain (feed):
        //   main.rs::run_play -> setup_online -> stage_online_identity
        //   -> ScreenGame::set_myroom_items / set_myroom_character.
        // Live caller chain (click):
        //   window press -> OnlineSession::press -> ScreenGame::click_dispatch
        //   -> click_side_screen -> click_myroom_side.
        // Live caller chain (paint):
        //   OnlineSession::paint (GameLoop) -> ScreenGame::paint_at
        //   -> paint_side -> paint_myroom -> paint_myroom_overlay.
        // Pure shell state plus a synthetic frame: no archives read.
        let mut game = myroom_open_overlay();
        game.show_myroom_panel(MyRoomPanel::Status);
        myroom_enable_gift_tab(&mut game);
        for (x, y) in [
            (10, 10),
            (100, 10),
            (150, 10),
            (200, 10),
            (300, 10),
            (400, 10),
            (450, 10),
            (10, 40),
        ] {
            game.click_myroom_side(x, y);
        }
        let selection = game.myroom();
        let equip_send = game.take_equip_send();
        let captions = game.myroom_money_captions();
        let pixels = paint_myroom_panel(&mut game);

        let mut hash = 0xcbf2_9ce4_8422_2325u64;
        hash_str(&mut hash, game.screen_name());
        hash_str(
            &mut hash,
            &format!("{selection:?}|{equip_send:?}|{captions:?}"),
        );
        for pixel in pixels {
            hash_u64(&mut hash, u64::from(pixel));
        }
        // #797 re-pin: the VACATE press opens the exe's no-selection
        // notice; #807 re-pin: the gift tab is switched before the
        // gift cell press, so that cell stays live under the exe's
        // tab-owned control set. Same screen, no wire.
        assert_eq!(
            hash, 13_048_635_776_834_777_667,
            "MyRoom ScreenGame cluster output drifted"
        );
    }

