    #[test]
    fn myroom_messenger_press_opens_the_pinned_liveness_sheet_and_ok_clears_it() {
        // Qualified B8 pack `f9d4a695…` pins MyRoom press `(644,580)`
        // → one-OK Information sheet, OK `(400,368)` clears it and host
        // navigation proceeds; b6 is byte-identical on the sheet.
        // Live chain: boot → Waiting → MyRoom side → staged MESSENGER
        // button → sheet → OK. No send is queued: Memoryer has no
        // messenger endpoint (environment fact, closed #345).
        use super::super::side::MYROOM_MESSENGER_CODE;
        let mut game = ScreenGame::new();
        walk_to_lobby(&mut game, Screen::Waiting);
        game.load_side_scene(
            vec![myroom_hit_placement(MYROOM_MESSENGER_CODE, 627, 571)],
            HashMap::new(),
        );
        assert!(game.visit_side(SideScreen::MyRoom));
        let paint = |game: &mut ScreenGame| {
            let mut buf = vec![0u32; 800 * 600];
            game.paint_at(
                &mut Frame {
                    buf: &mut buf,
                    w: 800,
                    h: 600,
                },
                0,
            );
            buf
        };
        let before = paint(&mut game);
        game.ingest_snapshot(&InputSnapshot::click_at(644, 580));
        assert!(game.messenger_liveness_open(), "the pinned sheet opens");
        let after = paint(&mut game);
        let ok_rect = crate::screens::paint::information_ok_fallback_rect();
        let ok_w = i32::try_from(ok_rect.w).expect("OK rect width fits");
        let ok_h = i32::try_from(ok_rect.h).expect("OK rect height fits");
        let inked = |buf: &[u32]| -> usize {
            (ok_rect.y..ok_rect.y + ok_h)
                .flat_map(|row| (ok_rect.x..ok_rect.x + ok_w).map(move |column| (row, column)))
                .filter(|(row, column)| buf[*row as usize * 800 + *column as usize] != 0)
                .count()
        };
        assert!(inked(&after) > inked(&before), "one-OK sheet paints ink");

        game.ingest_snapshot(&InputSnapshot::click_at(200, 200));
        assert!(game.messenger_liveness_open(), "host clicks are blocked");
        game.ingest_snapshot(&InputSnapshot::click_at(400, 368));
        assert!(!game.messenger_liveness_open(), "OK clears the sheet");
        assert_eq!(game.take_equip_send(), None);
        assert_eq!(game.take_gift_claim(), None);
    }

    #[test]
    fn messenger_host_press_paths_name_the_pinned_arm_and_the_open_arms() {
        // Spec #315 story 16 plus ticket #859: the five host MESSENGER
        // codes are pinned by the shipped ControlList. MyRoom (B8)
        // and Room (wave-2 `w2-messenger-exe`) have qualified press
        // packs pinning the one-OK liveness sheet; the other three
        // stay `N-HOST` gaps, never inferred from the sheet family.
        // Live caller chain (pinned arms): boot -> Waiting -> MyRoom
        // side -> staged MESSENGER code -> click_dispatch ->
        // MyRoomAction::MessengerLiveness -> messenger_liveness_open;
        // boot -> Room -> staged MESSENGER code -> click_room_control
        // -> RoomControlAction::MessengerLiveness -> the same notice.
        use super::super::side::MYROOM_MESSENGER_CODE;
        use crate::screens::messenger::MESSENGER_HOSTS;
        let expected = [
            (MessengerHost::Room, 0x1320_0048u32),
            (MessengerHost::Shop, 0x1420_00B8),
            (MessengerHost::MyRoom, 0x1520_006D),
            (MessengerHost::Waiting, 0x1620_006A),
            (MessengerHost::MusicShop, 0x1A20_0088),
        ];
        assert_eq!(MESSENGER_HOSTS.len(), expected.len());
        for (host, (declared, code)) in MESSENGER_HOSTS.into_iter().zip(expected) {
            assert_eq!(host, declared, "host order in the declaration");
            assert_eq!(host.control_code(), code, "{host:?} ControlList code");
            let pinned = matches!(host, MessengerHost::Room | MessengerHost::MyRoom);
            assert_eq!(
                host.exe_response_pin().is_some(),
                pinned,
                "{host:?} must not claim an unpinned response"
            );
            if !pinned {
                assert!(
                    host.next_evidence().contains("N-HOST"),
                    "{host:?} names its capture step"
                );
            }
        }
        assert_eq!(MessengerHost::MyRoom.control_code(), MYROOM_MESSENGER_CODE);
        assert_eq!(
            MessengerHost::MyRoom.exe_response_pin(),
            Some("B8 one-OK liveness sheet")
        );
        assert_eq!(
            MessengerHost::Room.exe_response_pin(),
            Some("W2 one-OK liveness sheet")
        );

        let mut game = ScreenGame::new();
        walk_to_lobby(&mut game, Screen::Waiting);
        game.load_side_scene(
            vec![myroom_hit_placement(
                MessengerHost::MyRoom.control_code(),
                627,
                571,
            )],
            HashMap::new(),
        );
        assert!(game.visit_side(SideScreen::MyRoom));
        assert!(!game.messenger_liveness_open(), "no sheet before the press");
        game.ingest_snapshot(&InputSnapshot::click_at(644, 580));
        assert!(
            game.messenger_liveness_open(),
            "the pinned MyRoom arm opens the liveness sheet"
        );
    }

    #[test]
    fn myroom_p0_controls_answer_nothing_and_queue_no_wire() {
        // Live caller chain:
        //   main.rs::run_play -> OnlineSession::ingest_snapshot
        //   -> ScreenGame::click_myroom_side -> myroom_action_at
        //   (P0 codes dispatch to no action) -> every session-bridge
        //   seam stays empty.
        // Pure shell state: no archives read, so no CI skip.
        use super::super::side::{
            myroom_action_for_code, myroom_p0_verdict, MyRoomAction, MYROOM_ALARM_CODE,
            MYROOM_ALARM_POPUP_CODE, MYROOM_BAGSORT_CODE, MYROOM_CONFERENCE_CODE,
            MYROOM_NOTICEBOARD_CODE, MYROOM_NOTICE_TEXT_CODE, MYROOM_PCROOMMARK_CODE,
            MYROOM_VACATE_CODE, MYROOM_WEBAVATAR_CODE,
        };

        // #798 re-pin: BAGSORT is no longer a P0 no-op; the exe's
        // 5038 send is wired and the verdict is retired.
        assert_eq!(
            myroom_action_for_code(MYROOM_BAGSORT_CODE),
            Some(MyRoomAction::BagSort)
        );
        assert_eq!(myroom_p0_verdict(MYROOM_BAGSORT_CODE), None);
        // #803/#804: CONFERENCE and WEBAVATAR answer now (modal +
        // notice); both verdicts retired like BAGSORT.
        for (code, action) in [
            (MYROOM_WEBAVATAR_CODE, MyRoomAction::ShowWebAvatar),
            (MYROOM_CONFERENCE_CODE, MyRoomAction::OpenConference),
        ] {
            assert_eq!(
                myroom_action_for_code(code),
                Some(action),
                "button {code:#X} dispatches its pinned action"
            );
            assert!(
                myroom_p0_verdict(code).is_none(),
                "P0 button {code:#X} carries a verdict"
            );
        }

        assert_eq!(
            myroom_action_for_code(MYROOM_BAGSORT_CODE),
            Some(MyRoomAction::BagSort),
            "BAGSORT now queues the pinned 5038"
        );
        assert_eq!(myroom_p0_verdict(MYROOM_BAGSORT_CODE), None);
        assert_eq!(
            myroom_action_for_code(MYROOM_CONFERENCE_CODE),
            Some(MyRoomAction::OpenConference),
            "CONFERENCE now opens its pinned modal sheet"
        );
        assert_eq!(myroom_p0_verdict(MYROOM_CONFERENCE_CODE), None);
        assert_eq!(
            myroom_action_for_code(MYROOM_WEBAVATAR_CODE),
            Some(MyRoomAction::ShowWebAvatar),
            "WEBAVATAR now posts the pinned register copy"
        );
        assert_eq!(myroom_p0_verdict(MYROOM_WEBAVATAR_CODE), None);

        // #811 retires the PCROOMMARK verdict: the staged pass word
        // now controls frame 1 of the pinned image control.
        assert_eq!(myroom_action_for_code(MYROOM_PCROOMMARK_CODE), None);
        assert_eq!(myroom_p0_verdict(MYROOM_PCROOMMARK_CODE), None);

        for code in [
            MYROOM_ALARM_CODE,
            MYROOM_ALARM_POPUP_CODE,
            MYROOM_NOTICE_TEXT_CODE,
            MYROOM_NOTICEBOARD_CODE,
        ] {
            assert_eq!(
                myroom_action_for_code(code),
                None,
                "P0 image {code:#X} dispatches nothing"
            );
            assert!(
                myroom_p0_verdict(code).is_some(),
                "P0 image {code:#X} carries a verdict"
            );
        }
        let mut game = myroom_open_overlay();
        game.ingest_snapshot(&InputSnapshot::click_at(11, 41));
        assert_eq!(game.take_equip_send(), None);
        assert_eq!(game.take_gift_claim(), None);
        let _ = MYROOM_VACATE_CODE;
    }

