    /// Synthetic options sheet: a `Dialog_*` backdrop (the
    /// dialog-relative origin) plus one 36x20 button placement per
    /// `(code, x, y)`, with a figure so the staged path answers.
    fn stage_option_buttons(
        game: &mut ScreenGame,
        tab: PlanetOptionTab,
        buttons: &[(u32, i32, i32)],
    ) {
        use crate::avatar::FigureLayer;
        let backdrop = match tab {
            PlanetOptionTab::Key => "Dialog_Option_Key.ojs",
            PlanetOptionTab::Sound => "Dialog_Option_Sound.ojs",
            PlanetOptionTab::Game => "Dialog_Option_Game.ojs",
        };
        let mut figure = AvatarFigure::default();
        figure.push_layer(FigureLayer {
            image: o2jam_render::Rgb555Image::decode(&[0x00, 0x7C], 1, 1).unwrap(),
            dx: 0,
            dy: 0,
            colorkey: 0x0000,
        });
        let mut placements = vec![ScenePlacement {
            role: PlacementRole::Single,
            id: "IDC_DIALOG".to_owned(),
            code: 0,
            sprite: Some(backdrop.to_owned()),
            rect: Rect {
                x: 0,
                y: 0,
                w: 800,
                h: 600,
            },
        }];
        for (index, (code, x, y)) in buttons.iter().enumerate() {
            placements.push(ScenePlacement {
                role: PlacementRole::Single,
                id: format!("IDC_BUTTON_{index}"),
                code: *code,
                sprite: None,
                rect: Rect {
                    x: *x,
                    y: *y,
                    w: 36,
                    h: 20,
                },
            });
        }
        game.load_planet_option_tab(
            tab,
            placements,
            HashMap::from([(backdrop.to_owned(), figure)]),
        );
    }

    /// Stage one options tab with a two-record button under a later-
    /// painted cover, for rest/hover/active frame guards.
    fn stage_option_frame_button(game: &mut ScreenGame, tab: PlanetOptionTab, code: u32) {
        use crate::avatar::FigureLayer;
        let cover_figure = |word: u16| {
            let mut figure = AvatarFigure::default();
            figure.push_layer(FigureLayer {
                image: o2jam_render::Rgb555Image::decode(
                    &word.to_le_bytes().repeat(40 * 20),
                    40,
                    20,
                )
                .expect("cover test face"),
                dx: 0,
                dy: 0,
                colorkey: 0xFFFF,
            });
            figure
        };
        let placement = |id: &str, code: u32, sprite: Option<&str>| ScenePlacement {
            role: PlacementRole::Single,
            id: id.to_owned(),
            code,
            sprite: sprite.map(str::to_owned),
            rect: Rect {
                x: 60,
                y: 100,
                w: 40,
                h: 20,
            },
        };
        game.load_planet_option_tab(
            tab,
            vec![
                coded_dialog_backdrop(0xAAAA_0001, 217, 42),
                placement("button", code, Some("option-button.ojs")),
                placement("cover", 0, Some("option-cover.ojs")),
            ],
            HashMap::from([
                (
                    "option-button.ojs".to_owned(),
                    chrome_two_layer_figure(40, 20),
                ),
                ("option-cover.ojs".to_owned(), cover_figure(0x7C00)),
            ]),
        );
    }

    /// Ink at the staged options button's sample pixel after one paint.
    fn option_frame_pixel(game: &mut ScreenGame) -> u32 {
        let mut buf = vec![0u32; 800 * 600];
        game.paint_at(
            &mut Frame {
                buf: &mut buf,
                w: 800,
                h: 600,
            },
            0,
        );
        buf[150 * 800 + 285]
    }

