    #[test]
    fn click_staged_select_row_commits_song_and_queues_4000() {
        // The host song pick commits through the real dialog: a row
        // click on the staged search table sets the room song (the
        // row's song id plus its difficulty slot) and queues the
        // `SetRoomMusic` 4000 send — the click path, not the direct
        // call. Row 1 is song 757 at the Normal slot; the staged
        // speed survives the pick.
        let mut game = ScreenGame::new();
        game.set_joined_room(waiting_room());
        game.load_select_music_scene(Vec::new(), HashMap::new());
        stage_waiting_song(&mut game);
        walk_to_waiting(&mut game);
        assert!(game.is_room_master());
        game.ingest_snapshot(&InputSnapshot::click_at(400, 150 + 23 + 11));
        let picked = game.selected_music().expect("row click commits the song");
        assert_eq!(picked.music_id, 757);
        assert_eq!(picked.difficulty, 1);
        assert_eq!(picked.speed, 3);
        assert!(game.has_pending_music_send());
        assert_eq!(game.take_music_send(), Some(picked));
        assert!(!game.has_pending_music_send());
        // A click outside the staged rows queues nothing.
        game.ingest_snapshot(&InputSnapshot::click_at(10, 10));
        assert!(!game.has_pending_music_send());
    }

    #[test]
    fn uninstalled_song_row_shows_the_notice_and_refuses_the_pick() {
        // Live caller chain (docs/live-path-reachability.md):
        //   main.rs::run_play -> stage_session_catalog
        //     (o2jam_shell::music_install::scan_installed_music ->
        //      session::OnlineSession::set_installed_music ->
        //      ScreenGame::set_installed_music)
        //   -> session::OnlineSession::set_song_catalog_with_labels
        //   -> ScreenGame::set_song_catalog_with_labels,
        // then the dialog click: ScreenGame::click_waiting_button
        // (MUSELECT) -> ScreenGame::click_select_music ->
        // ScreenGame::pick_select_music_row.
        // The install scan is synthetic here, so the guard runs with or
        // without install-root (CI has no game data).
        let mut game = ScreenGame::new();
        game.set_joined_room(waiting_room());
        game.load_select_music_scene(Vec::new(), HashMap::new());
        // The live order: the scan stages first, then the catalog takes
        // its answer (§1). Only 757's chart file is on disk; 770's is
        // not.
        game.set_installed_music(Some(o2jam_file::installed_music(["o2ma757.ojn"])));
        let blob = lanking_catalog_blob();
        let entries = o2jam_file::parse_ojn_list(&blob).unwrap();
        game.set_song_catalog(&entries);
        walk_to_waiting(&mut game);
        assert!(game.is_room_master());
        assert_eq!(game.select_music_notice(), None);
        // Rows 0-2 are 757 (installed), rows 3-5 are 770 (missing).
        game.ingest_snapshot(&InputSnapshot::click_at(400, 150 + 11));
        assert_eq!(
            game.take_music_send().map(|pick| pick.music_id),
            Some(757),
            "an installed row still picks"
        );
        game.ingest_snapshot(&InputSnapshot::click_at(400, 150 + 3 * 23 + 11));
        assert_eq!(
            game.select_music_notice(),
            Some(SELECT_NOT_DOWNLOADED_NOTICE),
            "the refused row raises the pinned notice (§3)"
        );
        assert!(
            !game.has_pending_music_send(),
            "a song without its chart file never queues a 4000 (§3)"
        );
        assert_eq!(
            game.selected_music().map(|pick| pick.music_id),
            Some(757),
            "the refused row leaves the staged song alone"
        );
    }

    #[test]
    fn a_promoted_chart_makes_its_dialog_row_selectable_again() {
        // Live chain: `session::OnlineSession::poll_music_downloads` ->
        // `ScreenGame::pump_music_downloads` -> `MusicDownload::pump`
        // (Temp promote) -> `ScreenGame::set_installed_music` -> the
        // same MUSELECT -> `click_select_music` ->
        // `pick_select_music_row` path the refusal guard walks. The
        // folders and chart bytes are synthetic (CI-safe).
        let root = std::env::temp_dir().join("recomp2jam-promote-selectable");
        let source = root.join("source");
        let music = root.join("Music");
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&source).expect("source dir");
        std::fs::create_dir_all(&music).expect("music dir");
        std::fs::write(source.join("o2ma770.ojn"), b"synthetic").expect("source chart");

        let mut game = ScreenGame::new();
        game.set_joined_room(waiting_room());
        game.load_select_music_scene(Vec::new(), HashMap::new());
        game.set_music_download_dirs(music.clone(), Some(source));
        game.set_installed_music(Some(o2jam_file::installed_music(["o2ma757.ojn"])));
        let blob = lanking_catalog_blob();
        let entries = o2jam_file::parse_ojn_list(&blob).unwrap();
        game.set_song_catalog(&entries);
        walk_to_waiting(&mut game);
        game.ingest_snapshot(&InputSnapshot::click_at(400, 150 + 3 * 23 + 11));
        assert_eq!(
            game.select_music_notice(),
            Some(SELECT_NOT_DOWNLOADED_NOTICE),
            "the missing chart refuses the row before the transfer"
        );
        assert!(!game.has_pending_music_send());

        assert!(game.begin_music_download(770));
        let completions = game.pump_music_downloads();
        assert_eq!(completions.len(), 1);
        assert_eq!(completions[0].file_name, "o2ma770.ojn");
        assert!(music.join("o2ma770.ojn").exists());
        assert!(!game.music_download().is_running());
        game.ingest_snapshot(&InputSnapshot::click_at(400, 150 + 3 * 23 + 11));
        assert_eq!(
            game.take_music_send().map(|pick| pick.music_id),
            Some(770),
            "the promoted chart makes the row pickable"
        );
        assert_eq!(game.select_music_notice(), None);
        let _ = std::fs::remove_dir_all(&root);
    }

