    #[test]
    fn create_room_commit_takes_the_untouched_default_title() {
        // Live chain: `main.rs::run_play` → winit click → `click_room_control`
        // (`RoomControlAction::Create`) → `open_create_room_dialog` →
        // `click_room_dialog` (Commit) → `CreateRoomForm::commit`.
        let mut game = game_with_open_create_dialog();
        let prefilled = game.create_room_form().title.clone();
        assert!(!prefilled.is_empty());
        game.click_room_dialog(20, 20);
        assert_eq!(game.room_dialog(), None);
        let body = game.take_create_room().expect("committed 2004");
        assert_eq!(
            body.title, prefilled,
            "the commit sends the prefilled default"
        );
    }

    #[test]
    fn create_room_cleared_default_title_commits_nothing() {
        // Live chain: `main.rs::run_play` → winit Backspace →
        // `delete_room_dialog_char` → `CreateRoomForm::pop_title` (the
        // selected default clears whole) → `click_room_dialog` (Commit)
        // → `CreateRoomForm::commit` returns `None`.
        let mut game = game_with_open_create_dialog();
        game.delete_room_dialog_char();
        assert_eq!(game.create_room_form().title, "");
        game.click_room_dialog(20, 20);
        assert_eq!(game.room_dialog(), Some(RoomDialog::CreateRoom));
        assert!(game.take_create_room().is_none());
    }

    #[test]
    fn create_room_create_clicks_the_parent_offset_rect_with_real_bytes() {
        // Real 7.55 bytes (skips without install-root): CREATE commits
        // at the #114 parent-offset rect, never at the verbatim storage
        // rect (ticket #134). The back sits at (188,71) with CREATE
        // dialog-local at (146,374), so the commit lands at (397,467)
        // while the storage center (209,396) answers nothing.
        use crate::screens::side::CREATE_ROOM_CREATE_CODE;
        use crate::staging::{stage_dialog, Dialog, StageContext};
        let mut game = ScreenGame::new();
        let Ok(bytes) = std::fs::read(
            std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../install-root/O2Jam/Image/Interface1.opi"),
        ) else {
            return;
        };
        let art = stage_dialog(&bytes, Dialog::CreateRoom, StageContext::default())
            .art
            .expect("create-room stages with real bytes");
        let placements = art.placements.clone();
        game.load_create_room_scene(art.placements, art.figures);
        game.menu_key(MenuKey::Back, true);
        game.click_planet(136, 88);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);
        game.open_create_room_dialog();
        game.push_room_dialog_char('x');
        assert_eq!(
            super::super::paint::dialog_origin(&placements),
            (188, 71),
            "the back rect authors the dialog origin"
        );
        game.click_room_dialog(209, 396);
        assert_eq!(
            game.room_dialog(),
            Some(RoomDialog::CreateRoom),
            "the verbatim storage center is dialog-local, never a hit"
        );
        assert!(game.take_create_room().is_none());
        click_staged_dialog_button(&mut game, &placements, CREATE_ROOM_CREATE_CODE);
        assert_eq!(game.room_dialog(), None);
        let body = game.take_create_room().expect("committed 2004");
        assert_eq!(body.title, "x");
    }

    /// Exe CREATE sheet pin (ticket #517): `~/scratch/evidence-room/
    /// create-fields-2/exe/artifacts/screenshots/
    /// pass-02-empty-password-frame.png` (sha256
    /// `70318790067b14ba91b45cec4ecd47df14ba7aad5bc54fbefef6147db3db671d`)
    /// shows the password edit empty beside the typed title, and the
    /// matching 2004 carries no lock. The staged `.bnd` edit rect must
    /// own focus, and an untouched edit must commit an empty password.
    #[test]
    fn staged_create_password_edit_feeds_the_committed_lock_flag() {
        use crate::screens::side::CREATE_ROOM_PASSWORD_CODE;
        use crate::staging::{stage_dialog, Dialog, StageContext};
        let Ok(bytes) = std::fs::read(
            std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../install-root/O2Jam/Image/Interface1.opi"),
        ) else {
            return;
        };
        let art = stage_dialog(&bytes, Dialog::CreateRoom, StageContext::default())
            .art
            .expect("create-room stages with real bytes");
        let placements = art.placements.clone();

        let mut game = ScreenGame::new();
        game.load_create_room_scene(art.placements, art.figures);
        game.menu_key(MenuKey::Back, true);
        game.click_planet(136, 88);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);
        game.open_create_room_dialog();
        assert_eq!(game.create_room_form().password, "");
        click_staged_dialog_button(&mut game, &placements, CREATE_ROOM_PASSWORD_CODE);
        for letter in "1234".chars() {
            game.push_room_dialog_char(letter);
        }
        assert_eq!(game.create_room_form().password, "1234");
        click_staged_dialog_button(
            &mut game,
            &placements,
            crate::screens::side::CREATE_ROOM_CREATE_CODE,
        );
        let locked = game.take_create_room().expect("committed 2004");
        assert!(locked.has_password);
        assert_eq!(locked.password, "1234");

        game.open_create_room_dialog();
        assert_eq!(game.create_room_form().password, "");
        click_staged_dialog_button(
            &mut game,
            &placements,
            crate::screens::side::CREATE_ROOM_CREATE_CODE,
        );
        let unlocked = game.take_create_room().expect("committed 2004");
        assert!(!unlocked.has_password);
        // #851: the exe 2004 builder substitutes the password string
        // "1" on the wire when the lock flag is clear (immediate
        // write at file 0x36455, FUN_00436360, ev_c68b010…); the
        // FORM password stays empty, the wire text does not.
        assert_eq!(
            unlocked.password, "1",
            "empty lock substitutes the exe's wire password"
        );
    }

