    #[test]
    fn shop_bag_pager_turns_over_staged_owned_inventory() {
        // Live caller chain:
        //   main.rs::run_play -> setup_online
        //   -> connect::connect_and_login_with_transport
        //   -> stage_online_identity -> ScreenGame::set_avatar_source
        //   -> ShopState::set_catalog (+ set_myroom_character on
        //   fetched boots for the owned ids), then click_shop on the
        //   staged BAGLEFT/RIGHT pager. The pager turns over owned
        //   goods in inventory order (zero/unknown ids skip); RIGHT
        //   holds at the end and LEFT wraps at the start (#784, static
        //   `0x1420004c/4d`). It never queues a send.
        let mut game = open_shop_board(25);
        game.set_myroom_character(myroom_test_character(vec![
            0, 3, 999, 1, 2, 5, 7, 9, 11, 13, 15, 17, 19, 21,
        ]));
        assert_eq!(game.shop_bag_pages(), 2);
        let first: Vec<u32> = game
            .shop_visible_bag()
            .iter()
            .map(|good| good.item_id)
            .collect();
        assert_eq!(first, vec![3, 1, 2, 5, 7, 9, 11, 13, 15, 17]);
        game.click_shop(410, 576);
        assert_eq!(game.shop_bag_page(), 1);
        let second: Vec<u32> = game
            .shop_visible_bag()
            .iter()
            .map(|good| good.item_id)
            .collect();
        assert_eq!(second, vec![19, 21]);
        game.click_shop(410, 576);
        assert_eq!(game.shop_bag_page(), 1, "bag NEXT holds past the end");
        game.click_shop(291, 576);
        assert_eq!(game.shop_bag_page(), 0);
        game.click_shop(291, 576);
        assert_eq!(game.shop_bag_page(), 1, "bag PREV wraps to the last page");
        assert_eq!(game.take_shop_buy(), None);
    }

    #[test]
    fn shop_row_prices_come_from_the_staged_catalog() {
        // Live caller chain:
        //   main.rs::run_play -> setup_online
        //   -> connect::connect_and_login_with_transport
        //   -> stage_online_identity -> ScreenGame::set_avatar_source
        //   -> ShopState::set_catalog. Per-row WON cells ink the staged
        //   catalog price word with no invented data (a zero price and
        //   a non-id price ride through untouched); the GEM cell has no
        //   pinned source and stays blank (the paint guard pins the
        //   dark rect).
        let priced = [(1u32, 777u32), (2, 0), (3, 2500)];
        let rows: Vec<o2jam_file::AvatarItemRow> = priced
            .iter()
            .map(|(item_id, price)| o2jam_file::AvatarItemRow {
                item_id: *item_id,
                item_type: 0,
                price: *price,
                params: [0; 4],
                flags: (0, 0),
                name: format!("Priced{item_id:02}"),
                description: String::new(),
                sprites: Vec::new(),
            })
            .collect();
        let mut game = ScreenGame::new();
        walk_to_waiting(&mut game);
        game.set_shop_catalog(&o2jam_file::AvatarItemTable { rows });
        let staged: Vec<(u32, u32)> = game
            .shop_visible_goods()
            .iter()
            .map(|good| (good.item_id, good.price))
            .collect();
        assert_eq!(staged, vec![(1, 777), (2, 0), (3, 2500)]);
    }

    #[test]
    fn shop_filter_scroll_and_cart_total_follow_the_sweep_frames() {
        // Live caller chain:
        //   main.rs::run_play -> ingest_snapshot -> ScreenGame::click_shop
        //   -> shop_action_at(FASHION / scroll RIGHT / ITEMBUY) ->
        //   ShopState::apply_action -> shop_cart_money_total.
        // Exe sweep `d4074ce7…` (FASHION highlight), `099d1ee6…`
        // (scroll changes cards/page) and `698f9ec8…` (cart press
        // negative): only the local tab state and board page move;
        // no wire frame is pinned for either press.
        use super::super::side::SHOP_CATEGORY_FIRST_CODE;
        use crate::avatar::PlacementRole;
        use o2jam_render::Rect;

        let mut game = open_shop_board(10);
        game.side_placements.push(ScenePlacement {
            role: PlacementRole::Single,
            id: String::new(),
            code: SHOP_CATEGORY_FIRST_CODE + 1,
            sprite: None,
            rect: Rect {
                x: 500,
                y: 0,
                w: 60,
                h: 25,
            },
        });
        assert_eq!(game.shop_category(), None);

        game.click_shop(528, 19);
        assert_eq!(game.shop_category(), Some(1), "FASHION tab is selected");
        assert!(
            game.take_shop_buy().is_none(),
            "filter press queues nothing"
        );
        assert!(game.shop_cart().is_empty());

        game.click_shop(261, 196);
        assert_eq!(game.shop_cart(), vec![1]);
        assert_eq!(game.shop_cart_money_total(), 100);
        game.click_shop(753, 379);
        assert_eq!(game.shop_page(), 1, "scroll RIGHT turns the catalogue");
        assert_eq!(game.shop_category(), Some(1), "scroll keeps the filter");
        assert!(game.take_shop_buy().is_none(), "scroll queues nothing");
    }

    #[test]
    fn shop_unwired_browse_chrome_lands_nowhere() {
        // Live caller chain: same catalog staging as the preview
        // guard, then click_shop on ControlList-named chrome the live
        // dump never stages (gender, submenu, ext-menu, planet
        // pager, per-row gifts, gift commit), plus
        // the music-shop TOP100 arm (#181: music-shop-only — the item
        // shop owns no TOP100 control), plus the paint-target codes
        // (icons, comment, gem cells, cart totals). Every one lands
        // nowhere: no cart check, no page turn, no preview, no send.
        let mut game = open_shop_board(10);
        let mut codes = vec![
            SHOP_GIRL_CODE,
            SHOP_BOY_CODE,
            SHOP_PLANET_UP_CODE,
            SHOP_PLANET_DOWN_CODE,
            SHOP_GIFTITEM_CODE,
            SHOP_EXTMENU_ON_CODE,
            SHOP_ITEMSHOW_FIRST_CODE,
            SHOP_MYBAGITEM_FIRST_CODE,
            SHOP_ITEMCOMMENT_CODE,
            SHOP_CART_CHECKGEM_CODE,
            SHOP_CART_CHECKMONEY_CODE,
            SHOP_ITEMGEM_FIRST_CODE,
            MSHOP_TOP100_CODE,
        ];
        for slot in 0..SHOP_CATEGORY_BUTTONS as u32 {
            codes.push(SHOP_CATEGORY_FIRST_CODE + slot);
        }
        for slot in 0..SHOP_SUBMENU_BUTTONS as u32 {
            codes.push(SHOP_SUBMENU_FIRST_CODE + slot);
        }
        for slot in 0..8u32 {
            codes.push(SHOP_ITEMGIFT_FIRST_CODE + slot);
        }
        for slot in 0..SHOP_EXTMENU_BUTTONS as u32 {
            codes.push(SHOP_EXTMENU_FIRST_CODE + slot);
        }
        let area = |code: u32, index: usize| ScenePlacement {
            role: PlacementRole::Single,
            id: String::new(),
            code,
            sprite: None,
            rect: Rect {
                x: 10 + (index as i32) * 15,
                y: 30,
                w: 10,
                h: 10,
            },
        };
        for (index, code) in codes.iter().enumerate() {
            game.side_placements.push(area(*code, index));
        }
        for (index, _) in codes.iter().enumerate() {
            game.click_shop(10 + (index as i32) * 15 + 5, 35);
        }
        assert!(game.shop_cart().is_empty());
        assert_eq!(game.shop_page(), 0);
        assert_eq!(game.shop_cart_page(), 0);
        assert_eq!(game.shop_bag_page(), 0);
        assert_eq!(game.shop_preview(), None);
        assert_eq!(game.take_shop_buy(), None);
        assert_eq!(
            game.take_refresh_bag(),
            None,
            "BAGSORT owns the static 5038, not this no-op family"
        );
        assert_eq!(game.side(), Some(SideScreen::Shop));
    }

    #[test]
    fn cart_pager_steps_only_while_the_cart_face_flag_is_set() {
        // Live caller chain:
        //   main.rs::run_play -> ingest_snapshot -> click_side_screen ->
        //   click_shop(ITEMBUY/MYBACK_POS/MYCART_POS/MYCART_RIGHT/LEFT)
        //   -> ShopState::apply_action -> paint cart page readout.
        // Static arms `0x14200072/73` (ev_f3ad15be…) step page `0x8ce`
        // modulo count `0x8cf` only when flag `0x8cd` is set; MYBACK_POS
        // clears it and MYCART_POS sets it (files `0xa5a75`/`0xa5b63`).
        // Multi-page cart fixture: six checked goods over five rows.
        let mut game = open_shop_board(12);
        for slot in 0..6i32 {
            game.click_shop(221 + (slot % 4) * 141, 188 + (slot / 4) * 153);
        }
        assert_eq!(game.shop_cart().len(), 6);
        assert_eq!(game.shop_cart_pages(), 2);
        for (code, x) in [
            (super::super::side::SHOP_MYBACK_POS_CODE, 510),
            (super::super::side::SHOP_MYCART_POS_CODE, 560),
        ] {
            game.side_placements.push(ScenePlacement {
                role: PlacementRole::Single,
                id: format!("CART_FACE_{code:X}"),
                code,
                sprite: None,
                rect: Rect {
                    x,
                    y: 30,
                    w: 40,
                    h: 20,
                },
            });
        }

        game.click_shop(515, 40);
        game.click_shop(320, 570);
        assert_eq!(game.shop_cart_page(), 0, "cleared face flag blocks RIGHT");

        game.click_shop(565, 40);
        game.click_shop(320, 570);
        assert_eq!(game.shop_cart_page(), 1, "set face flag allows RIGHT");
        game.click_shop(320, 570);
        assert_eq!(game.shop_cart_page(), 1, "RIGHT holds at the last page");
        game.click_shop(220, 570);
        assert_eq!(game.shop_cart_page(), 0, "LEFT returns to the first page");
    }

