    #[test]
    fn music_buy_folds_owned_songs_into_shop_board_and_select() {
        // Live caller chain:
        //   main.rs::run_play -> setup_online -> stage_online_identity
        //   -> ScreenGame::set_song_catalog (the catalog fans out to
        //   the select table and both boards) -> ScreenGame::click_music_shop
        //   (the cart BUYITEM queues the pinned 5010)
        //   -> OnlineSession::paint -> flush_music_buy (5010 send)
        //   -> poll_music_buy -> drain_music_buy (5011)
        //   -> ScreenGame::apply_music_purchase_response
        //   -> MusicShopState::fold_purchased_songs (board)
        //   + WalletState::apply_music_purchase (wallet).
        //   Readouts: music_shop_visible_rows (OWNED caption) + select_songs.
        // Tier 0 seam: proves the fold at the seam; the Tier 2 gateway
        // guard proves the 5010/5011 wire ride.
        use super::super::side::music_shop_buy_caption;
        use o2jam_net::shop::MusicEntry;

        let mut game = ScreenGame::new();
        walk_to_waiting(&mut game);
        let mut blob = Vec::new();
        blob.extend_from_slice(&lanking_record(757, 124.0, "First", "Band"));
        blob.extend_from_slice(&lanking_record(758, 130.0, "Second", "Set"));
        let entries = o2jam_file::parse_ojn_list(&blob).unwrap();
        game.set_song_catalog(&entries);
        game.stage_music_shop_board(o2jam_net::play::MusicListAnswer {
            entries: Vec::new(),
            free_music: false,
        });
        game.music_shop_cart_push(757);
        assert_eq!(game.music_shop_cart(), vec![757]);
        assert!(game
            .music_shop_visible_rows()
            .iter()
            .map(music_shop_buy_caption)
            .all(|caption| caption.is_empty()));

        game.apply_music_purchase_response(&SyncMusicPurchaseResponse {
            gem: 1000,
            point: 250,
            o2_cash: 5000,
            music_cash: 120,
            item_cash: 340,
            cash_point: 56,
            music_list: vec![MusicEntry {
                music_id: 757,
                day: 0,
                month: 0,
                year: 0,
                hour: 0,
                minute: 0,
            }],
            gift_boxes_raw: Vec::new(),
            free_pass_extension_days: 0,
        });

        assert!(game.music_shop_cart().is_empty());
        assert!(game.select_songs().iter().any(|song| song.song_id == 757));
        let owned: Vec<u32> = game
            .music_shop_visible_rows()
            .iter()
            .filter(|row| music_shop_buy_caption(row) == "OWNED")
            .map(|row| row.song.song_id)
            .collect();
        assert_eq!(owned, vec![757]);
    }

    #[test]
    fn music_shop_row_buy_adds_the_catalog_song_and_invokes_buyitem() {
        // Live caller chain: main.rs::run_play -> stage_live_art ->
        // visit_side(MusicShop) -> GameLoop::mouse_click ->
        // click_music_shop -> music_shop_action_at -> music_shop_buy_slot
        // (the two tiled row buy rect arrays) -> MusicShopState::apply_action
        // (BuyRow) -> click_music_shop's MusicShopEffect::Buy ->
        // outbox.pending_music_buy (5010). Exe FUN_004c7f70 indexes the
        // catalog by page*5+row, refuses at ten bag entries with VA
        // 0x64a5f0, posts VA 0x6486a4 on a duplicate, and invokes the
        // BUYITEM control on success (ev_26ac6479..., ticket #833).
        let mut game = open_music_shop_board(11);

        game.click_music_shop(350, 160);
        assert_eq!(game.music_shop_cart(), vec![757], "row 0 buys song 757");
        assert_eq!(game.music_shop_bag_item_code(757), Some(MSHOP_BAG_GEM_CODE));
        assert_eq!(
            game.music_shop_buyitem_invoked(),
            Some(MSHOP_BUYITEM_INVOKE_CODE)
        );
        assert!(game.take_music_buy().is_some(), "the buy queues 5010");

        game.click_music_shop(350, 160);
        assert_eq!(
            game.music_shop_notice(),
            Some((MusicShopNotice::DuplicateCartItem, MSHOP_GEM_BUY_CODE))
        );
        assert_eq!(game.music_shop_cart(), vec![757], "no duplicate add");
        assert!(game.take_music_buy().is_none(), "a duplicate buys nothing");

        game.click_music_shop(340, 542);
        assert_eq!(game.music_shop_page(), 1);
        game.click_music_shop(350, 160);
        game.click_music_shop(350, 263);
        assert_eq!(
            game.music_shop_cart(),
            vec![757, 762, 763],
            "page*5+row picks the catalog songs"
        );
        assert_eq!(game.music_shop_bag_item_code(763), Some(MSHOP_BAG_WON_CODE));
        assert_eq!(game.take_music_buy().map(|_| 1), Some(1), "two buys queued");
        game.take_music_buy();

        for song_id in [758, 759, 760, 761, 764, 765, 766] {
            game.music_shop_bag_push(song_id, true);
        }
        assert_eq!(game.music_shop_bag_count(), 10);
        game.click_music_shop(340, 542);
        assert_eq!(game.music_shop_page(), 2);
        game.click_music_shop(350, 160);
        assert_eq!(
            game.music_shop_notice().map(|(notice, _)| notice),
            Some(MusicShopNotice::CartFull)
        );
        assert_eq!(game.music_shop_bag_count(), 10, "the cap holds");
        assert_eq!(game.music_shop_bag_item_code(767), None);
        assert!(game.take_music_buy().is_none(), "the cap buys nothing");
    }

    /// Fund the four wallet words the music-shop checkout compares,
    /// then stage both a gem-priced and a won-priced catalog song.
    fn open_funded_music_checkout() -> ScreenGame {
        let mut game = open_music_shop_board(2);
        game.stage_music_shop_prices(&[
            o2jam_file::OjnMidParamEntry {
                song_id: 757,
                param_a: 100,
                param_b: 40,
                anchor: o2jam_file::OJN_MID_TABLE3_ANCHOR,
            },
            o2jam_file::OjnMidParamEntry {
                song_id: 758,
                param_a: 100,
                param_b: 0,
                anchor: o2jam_file::OJN_MID_TABLE3_ANCHOR,
            },
        ]);
        game.wallet = WalletState {
            gem: Some(500),
            o2_cash: Some(500),
            music_cash: Some(500),
            item_cash: Some(500),
            ..WalletState::default()
        };
        game
    }

    #[test]
    fn a_music_shop_buy_press_writes_mode_one_and_queues_the_5015() {
        // Live caller chain:
        //   main.rs::run_play -> stage_live_art -> visit_side(MusicShop)
        //   -> GameLoop::mouse_click -> click_music_shop(BuyRow, CartBuy)
        //   -> MusicShopState::approve_checkout -> PendingOutbox
        //   -> OnlineSession::poll_wire -> flush_start_payment -> 5015.
        // Exe FUN_004c7f70 case 0x1A20005D: bag totals vs globals
        // 0x768B4C/50/54 and 0x768B44, then state +0x14D = 1 and
        // virtual 0x1397 (ev_26ac6479…). The qualified tap is OPEN.
        let mut game = open_funded_music_checkout();
        game.click_music_shop(350, 160);
        game.click_music_shop(424, 529);

        assert_eq!(
            game.music_shop_payment_mode(),
            Some(super::super::side::CheckoutMode::Buy)
        );
        assert_eq!(game.take_start_payment(), Some(StartPayment));
        assert_eq!(game.take_start_payment(), None, "one press sends once");
    }

