    #[test]
    fn owned_rows_show_their_own_check_and_download_marks_from_boot() {
        // Live caller chain: main.rs::run_play -> setup_online ->
        // ScreenGame::stage_music_shop_board (4031 ids) +
        // ScreenGame::set_installed_music (local charts) ->
        // visit_side(MusicShop) -> GameLoop::mouse_click ->
        // click_music_shop -> MusicShopState::apply_action(OwnedRow)
        // -> paint_side owned-row marks. The twelve row codes and
        // the offsets -2/-4 are pinned; the two mark meanings stay
        // OPEN, so the guard names check vs installed, not a wire.
        let mut game = ScreenGame::new();
        walk_to_waiting(&mut game);
        let mut blob = Vec::new();
        blob.extend_from_slice(&lanking_record(757, 124.0, "First", "Band"));
        blob.extend_from_slice(&lanking_record(758, 130.0, "Second", "Band"));
        let entries = o2jam_file::parse_ojn_list(&blob).unwrap();
        game.set_song_catalog(&entries);
        game.stage_music_shop_board(MusicListAnswer {
            entries: vec![
                MusicListEntry {
                    id: 757,
                    notes_ex: 3,
                    notes_nx: 7,
                    notes_hx: 10,
                },
                MusicListEntry {
                    id: 758,
                    notes_ex: 3,
                    notes_nx: 7,
                    notes_hx: 10,
                },
            ],
            free_music: false,
        });
        game.set_installed_music(Some(o2jam_file::installed_music(["o2ma757.ojn"])));
        let placements = (0..12u32)
            .map(|slot| ScenePlacement {
                role: PlacementRole::Single,
                id: String::new(),
                code: MSHOP_OWNED_FIRST_CODE + slot,
                sprite: None,
                rect: Rect {
                    x: 10,
                    y: 20 + slot as i32 * 30,
                    w: 20,
                    h: 20,
                },
            })
            .collect();
        game.load_side_scene(placements, HashMap::new());
        assert!(game.visit_side(SideScreen::MusicShop));

        let rows = game.music_shop_owned_rows();
        assert_eq!(rows.len(), 2);
        assert!(rows[0].installed);
        assert!(!rows[1].installed);
        assert!(rows.iter().all(|row| !row.marked));
        game.click_music_shop(20, 30);
        let rows = game.music_shop_owned_rows();
        assert!(rows[0].marked, "clicking its row marks the first song");
        assert!(!rows[1].marked, "the other row keeps its own mark");

        let mut buf = vec![0_u32; 800 * 600];
        game.paint_at(
            &mut Frame {
                buf: &mut buf,
                w: 800,
                h: 600,
            },
            0,
        );
        let first_check = buf[(20 + 20 - 4) * 800 + (10 + 20 - 2)];
        let second_check = buf[(50 + 20 - 4) * 800 + (10 + 20 - 2)];
        assert_ne!(first_check, second_check, "only the checked row inks");
        let first_status = buf[25 * 800 + 16];
        let second_status = buf[55 * 800 + 16];
        assert_ne!(first_status, second_status, "installed status is per row");
    }

    #[test]
    fn music_shop_installed_mark_comes_from_the_local_chart_scan() {
        // Live caller chain: main.rs::run_play -> assemble_online_session ->
        // setup_online (install scan) -> ScreenGame::set_installed_music ->
        // MusicShopState::set_installed -> visible_rows ->
        // paint_music_shop_rows. The 4031 board only annotates ownership;
        // the local `o2ma<id>.ojn` scan names the installed mark (§1).
        // No install-root read: a synthetic chart name feeds the pure seat.
        let mut game = open_music_shop_board(2);
        game.set_installed_music(Some(o2jam_file::installed_music(["o2ma757.ojn"])));

        let rows = game.music_shop_visible_rows();
        assert_eq!(rows.len(), 2);
        assert!(rows[0].installed, "the local chart marks its row installed");
        assert!(!rows[1].installed, "no local chart leaves the row unmarked");

        let mut buf = vec![0_u32; 800 * 600];
        game.paint_at(
            &mut Frame {
                buf: &mut buf,
                w: 800,
                h: 600,
            },
            0,
        );
        let installed_pixel = buf[106 * 800 + 20];
        let missing_pixel = buf[190 * 800 + 20];
        assert_eq!(installed_pixel, pack_xrgb(0x50, 0xE0, 0x70));
        assert_ne!(
            installed_pixel, missing_pixel,
            "only the installed row inks"
        );
    }

