        game.ingest_snapshot(&InputSnapshot::click_at(261, 196));
        assert_eq!(game.shop_cart(), vec![2, 3, 4, 5, 6, 7, 8, 9]);
        game.ingest_snapshot(&InputSnapshot::click_at(753, 379));
