    #[test]
    fn firststep_press_loses_to_an_armed_loading_gate() {
        // Spec #313 story 20. Live chain: boot -> Room -> staged FIRSTSTEP
        // -> `ScreenGame::ingest_snapshot` -> `click_dispatch` ->
        // `click_room_control` -> `enter_room_side_with_enter_shop` ->
        // `visit_side(Tutorial)`. Statics pin one pending-state word in the
        // exe (`0x478c50` writes parent +0x54; `0x477990` consumes it) and
        // an unconditional FIRSTSTEP arm (`0x495110`); they do not pin
        // which of a start and a side visit wins in one frame. Conservative
        // ASSUMED order until `N-LOADING`: a qualified pack with both frames
        // and a shared trace id. Seam suffices here because the host dispatch
        // boundary is the whole decision: no display or wire is involved.
        let mut game = room_lobby_with_control(0x1320_0032, "IDC_BUTTON_SROOM_FIRSTSTEP");
        game.set_selected_music(SetRoomMusic {
            music_id: 757,
            difficulty: 1,
            speed: 0,
        });
        game.catalog_songs = vec![super::super::side::staged_song(757)];
        game.with_audio(Box::new(o2jam_audio::NullBackend::new()), HashMap::new());
        game.set_loading_status(LoadingStatus {
            progress: 1.0,
            title: "First".to_owned(),
            artist: "Band".to_owned(),
        });
        assert!(game.loading_gate_ready(), "song start gate is armed");

        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(
            game.side(),
            None,
            "FIRSTSTEP must not mount Tutorial while the gate is armed"
        );
        assert_eq!(game.tutorial_chart_globals(), None, "no entry globals");
        assert_eq!(game.screen(), Screen::Room, "the gate keeps its host");

        game.clear_loading();
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(
            game.side(),
            Some(SideScreen::Tutorial),
            "the same press enters once the gate is idle"
        );
    }

    /// Filter tabs select the list family locally (ticket #416). The
    /// 2002 parameter the exe may send on a tab press stays OPEN — no
    /// pack pins one — so this guard covers the staged-rect click and
    /// the rows the lobby paints, not a wire send.
    #[test]
    fn room_filter_tabs_keep_only_their_family_of_rows() {
        use o2jam_net::GameMode;
        let mut game = ScreenGame::new();
        let mut rooms = two_rooms();
        rooms[1].game_mode = GameMode::Live.as_u8();
        let normal_title = rooms[0].title.clone();
        let live_title = rooms[1].title.clone();
        game.set_rooms(rooms);
        game.menu_key(MenuKey::Back, true);
        game.click_planet(136, 88);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);

        let placements = [
            (0x1320_1003u32, 10),
            (0x1320_1004u32, 60),
            (0x1320_1005u32, 110),
        ]
        .into_iter()
        .map(|(code, x)| ScenePlacement {
            role: PlacementRole::Single,
            id: format!("FILTER_{code:X}"),
            code,
            sprite: None,
            rect: Rect {
                x,
                y: 10,
                w: 30,
                h: 30,
            },
        })
        .collect();
        game.load_scene(Screen::Room, placements, HashMap::new());

        game.ingest_snapshot(&InputSnapshot::click_at(75, 25));
        assert_eq!(game.room_filter(), RoomListFilter::Normal);
        let noop = game.room_control_noop().expect("the send stays OPEN");
        assert_eq!(noop.id, "IDC_BUTTON_SROOM_SHOW_NORMALMODE");
        assert!(noop.next_step.contains("2002"));
        let titles: Vec<&str> = game
            .listed_rooms()
            .iter()
            .map(|room| room.title.as_str())
            .collect();
        assert_eq!(titles, vec![normal_title.as_str()]);

        game.ingest_snapshot(&InputSnapshot::click_at(125, 25));
        assert_eq!(game.room_filter(), RoomListFilter::Live);
        let titles: Vec<&str> = game
            .listed_rooms()
            .iter()
            .map(|room| room.title.as_str())
            .collect();
        assert_eq!(titles, vec![live_title.as_str()]);

        game.ingest_snapshot(&InputSnapshot::click_at(25, 25));
        assert_eq!(game.room_filter(), RoomListFilter::All);
        assert_eq!(game.listed_rooms().len(), 2);
    }

    #[test]
    fn firststep_tutorial_entry_cues_the_pinned_tutorial_ojm_record() {
        // Live chain: main.rs::run_play -> setup_chart_audio ->
        // set_tutorial_ojm_bank -> boot -> Planet -> Channel -> Room
        // -> staged FIRSTSTEP click -> ScreenGame::visit_side ->
        // tutorial entry cue -> AudioBackend::set_scene_bgm. The state
        // helper at exe file 0xf0950 pushes "Tutorial.ojm" at 0xf0a48,
        // loads it at 0xf0a50, then calls the OJM play helper at
        // 0xf0ab0 (REA ev_c9875194…, ev_9f2d0d8…, ev_e25488ee…).
        // Chart markers 0x04000001..0x040000C pin the 12 mode-3
        // records; which one sounds stays OPEN (N-AUDIO A/B).
        use o2jam_audio::AudioError;
        use std::cell::RefCell;
        use std::rc::Rc;

        struct CueQueueProbe {
            peaks: Rc<RefCell<Vec<i32>>>,
        }
        impl AudioBackend for CueQueueProbe {
            fn play_pcm(&mut self, _pcm: &PcmSamples) -> Result<(), AudioError> {
                Ok(())
            }
            fn set_scene_bgm(
                &mut self,
                pcm: Option<&PcmSamples>,
                _repeat: bool,
            ) -> Result<(), AudioError> {
                let peak = pcm.map_or(0, |pcm| {
                    pcm.samples
                        .iter()
                        .map(|sample| i32::from(*sample).abs())
                        .max()
                        .unwrap_or(0)
                });
                self.peaks.borrow_mut().push(peak);
                Ok(())
            }
            fn samples_played(&self) -> u64 {
                0
            }
        }

        let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../install-root/O2Jam/Music/Tutorial.ojm");
        let Ok(bytes) = std::fs::read(&path) else {
            println!("skip: no install-root Tutorial.ojm");
            return;
        };
        let tables = o2jam_file::parse_new_variant_entries(&bytes).expect("parse Tutorial.ojm");
        let first = tables.mode3.first().expect("bgsplit-01 record");
        let body = first.sample_bytes(&bytes).expect("bgsplit-01 bytes");
        let pcm = o2jam_audio::decode_vorbis(body).expect("decode bgsplit-01");
        let peak = pcm
            .samples
            .iter()
            .map(|sample| i32::from(*sample).abs())
            .max()
            .unwrap_or(0);
        assert!(peak > 0, "the shipped first BGM record carries sound");

        let peaks = Rc::new(RefCell::new(Vec::new()));
        let probe = CueQueueProbe {
            peaks: Rc::clone(&peaks),
        };
        let mut game = ScreenGame::new();
        game.with_audio(Box::new(probe), HashMap::new());
        game.stage_scene_bgm(marker_bank(&[3]));
        game.set_tutorial_ojm_bank(vec![Some(pcm)]);
        game.set_channels(two_channels());
        game.set_rooms(two_rooms());
        game.menu_key(MenuKey::Back, true);
        game.click_planet(136, 88);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);
        game.load_scene(
            Screen::Room,
            vec![ScenePlacement {
                role: PlacementRole::Single,
                id: "IDC_BUTTON_SROOM_FIRSTSTEP".to_owned(),
                code: 0x1320_0032,
                sprite: None,
                rect: ROOM_CONTROL_TEST_RECT,
            }],
            HashMap::new(),
        );
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(game.side(), Some(SideScreen::Tutorial));
        assert_eq!(
            game.scene_bgm_selection(),
            Some(BgmSelection {
                record: 1,
                repeat: true
            }),
            "Tutorial.ojm record 1 is cued at entry"
        );
        assert_eq!(
            peaks.borrow().last().copied(),
            Some(peak),
            "the cued record's PCM reaches the backend queue"
        );
    }

    /// #863 row 22: the exe's tutorial update advances the OJM record
    /// when chart time passes a page deadline (update `0x4f19e0`,
    /// `FUN_0042f870` sets `+0x134` to `page-1`). A static record-1
    /// loop keeps the selection at 1 and fails here. Live chain:
    /// boot → Planet → Channel → Room → FIRSTSTEP → Tutorial paint
    /// at the page-2 deadline (13 * 2.4 s + 1.4 s ≈ 32.6 s at BPM 100).
    #[test]
    fn tutorial_ojm_advances_at_the_pinned_page_deadline() {
        let pushes = Rc::new(RefCell::new(Vec::new()));
        let effects = Rc::new(RefCell::new(Vec::new()));
        let mut game = room_lobby_with_control(0x1320_0032, "IDC_BUTTON_SROOM_FIRSTSTEP");
        game.with_audio(cue_log_backend(&pushes, &effects), HashMap::new());
        let bank = (1..=12)
            .map(|marker| {
                Some(o2jam_audio::PcmSamples {
                    samples: vec![marker; 441],
                    sample_rate: 44_100,
                    channels: 1,
                })
            })
            .collect();
        game.set_tutorial_ojm_bank(bank);
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(game.side(), Some(SideScreen::Tutorial));
        assert_eq!(game.scene_bgm_selection().map(|cue| cue.record), Some(1));

        let paint_at = |game: &mut ScreenGame, now_ms: u64| {
            let mut buf = vec![0u32; 800 * 600];
            game.paint_at(
                &mut Frame {
                    buf: &mut buf,
                    w: 800,
                    h: 600,
                },
                now_ms,
            );
        };
        paint_at(&mut game, 0);
        assert_eq!(
            game.scene_bgm_selection().map(|cue| cue.record),
            Some(1),
            "page 1 holds the entry record"
        );
        paint_at(&mut game, 33_000);
        assert_eq!(
            game.scene_bgm_selection().map(|cue| cue.record),
            Some(2),
            "page 2 cues the second mode-3 record"
        );
        assert_eq!(
            pushes.borrow().as_slice(),
            &[1, 2],
            "the backend receives the entry cue then the page-2 sample"
        );
    }

    /// Live chain: boot -> Planet -> Channel -> Room -> FIRSTSTEP click
    /// -> window present -> `OnlineSession::paint` -> `ScreenGame::paint`
    /// -> `paint_side` -> tutorial chart and page deadlines. The standard
    /// boot never enters Playing, so no song sample anchor exists here;
    /// a parked backend must still let the visit's own clock cross a page
    /// deadline (exe update `0x4f19e0` reads its ms clock at `0x5711e0`).
    #[test]
    fn tutorial_chart_advances_on_visit_wall_time_when_song_samples_are_parked() {
        let pushes = Rc::new(RefCell::new(Vec::new()));
        let effects = Rc::new(RefCell::new(Vec::new()));
        let mut game = room_lobby_with_control(0x1320_0032, "IDC_BUTTON_SROOM_FIRSTSTEP");
        game.with_audio(cue_log_backend(&pushes, &effects), HashMap::new());
        game.set_tutorial_ojm_bank(
            (1..=12)
                .map(|marker| {
                    Some(o2jam_audio::PcmSamples {
                        samples: vec![marker; 441],
                        sample_rate: 44_100,
                        channels: 1,
                    })
                })
                .collect(),
        );
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(game.side(), Some(SideScreen::Tutorial));
        assert_eq!(game.scene_bgm_selection().map(|cue| cue.record), Some(1));

        let paint = |game: &mut ScreenGame| {
            let mut buf = vec![0u32; 800 * 600];
            game.paint(&mut Frame {
                buf: &mut buf,
                w: 800,
                h: 600,
            });
        };
        // The first live frame latches the chart origin; earlier page
        // guards use the explicit `paint_at` seam and stay unchanged.
        paint(&mut game);
        assert_eq!(
            game.scene_bgm_selection().map(|cue| cue.record),
            Some(1),
            "entry holds the first page"
        );

        game.set_tutorial_wall_elapsed(std::time::Duration::from_millis(33_000));
        paint(&mut game);

        assert_eq!(
            game.scene_bgm_selection().map(|cue| cue.record),
            Some(2),
            "page 2 crosses at 13 * 2.4 s + 1.4 s with sampled audio parked"
        );
    }

    #[test]
    fn firststep_tutorial_exit_click_returns_to_room_and_recues_its_bgm() {
        // Live chain: boot → Planet → Channel → Room → staged FIRSTSTEP
        // click → Tutorial → bottom-right exit press → opening Room.
        // Boot1 input log `cee8b7d5…1913` clicks `(777,567)`; the next
        // frame `ed1bf56e…7b46` is the Room board with no modal. Boot
        // stages both banks: Tutorial.ojm record 1 sounds on entry and
        // the exit press re-cues BGM.ojm record 3.
        let mut game = ScreenGame::new();
        game.with_audio(Box::new(o2jam_audio::NullBackend::new()), HashMap::new());
        let mut bank = vec![None; 10];
        bank[2] = Some(o2jam_audio::PcmSamples {
            samples: vec![3; 441],
            sample_rate: 44_100,
            channels: 1,
        });
        game.stage_scene_bgm(bank);
        game.set_tutorial_ojm_bank(tutorial_cue_bank());
        game.set_channels(two_channels());
        game.set_rooms(two_rooms());
        game.menu_key(MenuKey::Back, true);
        game.click_planet(136, 88);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);
        game.load_scene(
            Screen::Room,
            vec![ScenePlacement {
                role: PlacementRole::Single,
                id: "IDC_BUTTON_SROOM_FIRSTSTEP".to_owned(),
                code: 0x1320_0032,
                sprite: None,
                rect: ROOM_CONTROL_TEST_RECT,
            }],
            HashMap::new(),
        );
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(game.side(), Some(SideScreen::Tutorial));
        assert_eq!(
            game.scene_bgm_selection(),
            Some(BgmSelection {
                record: 1,
                repeat: true
            }),
            "Tutorial.ojm record 1 plays before the exit press"
        );

        game.ingest_snapshot(&InputSnapshot::click_at(777, 567));
        assert_eq!(game.side(), None, "exit leaves the side visit");
        assert_eq!(game.screen(), Screen::Room, "opening lobby returns");
        assert_eq!(game.planet_modal(), None, "no modal on return");
        assert_eq!(game.scene_bgm_selection().map(|cue| cue.record), Some(3));
    }

